// KONSEP 1 — MIDNIGHT COUNTDOWN CLOCK
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function buildScene(width, height) {
  const u = Math.min(width, height);
  const rnd = rng(20270101);

  // Posisi jam (kanan), copy space di kiri
  const R = u * 0.29;
  const cx = width * 0.735;
  const cy = height * 0.48;
  const orbitR = R * 1.14;
  const ringOuter = orbitR + u * 0.012;

  // Jalur confetti (lane) — tidak pernah melewati area jam
  const laneX = [];
  for (let i = 0; i < 4; i++) laneX.push(u * (0.07 + 0.037 * i));
  laneX.push(cx + ringOuter + u * 0.045);
  laneX.push(cx + ringOuter + u * 0.082);

  const skylineTop = height - u * 0.12;
  const confettiMargin = u * 0.04;
  const perLane = 7;
  const pieces = [];
  laneX.forEach((x, li) => {
    const off = rnd();
    const cyc = li % 2 === 0 ? 2 : 1;
    for (let j = 0; j < perLane; j++) {
      pieces.push({
        x: x,
        phase: (j + off) / perLane,
        cyc: cyc,
        type: (j + li) % 4,
        col: (j * 2 + li) % 4,
        rot: rnd() * TAU,
        rc: ((j + li) % 2) + 1,
        dir: (j * 3 + li) % 2 ? 1 : -1,
        fc: 2 + ((j + li) % 2),
        fph: rnd() * TAU,
        sk: 1 + (li % 2),
        sph: rnd() * TAU,
        amp: u * 0.0042
      });
    }
  });

  // Bintang (hindari jam, jalur confetti, dan skyline)
  const bands = [
    [laneX[0] - u * 0.04, laneX[3] + u * 0.04],
    [laneX[4] - u * 0.04, laneX[5] + u * 0.04]
  ];
  const stars = [];
  let tries = 0;
  while (stars.length < 80 && tries < 6000) {
    tries++;
    const x = u * 0.03 + rnd() * (width - u * 0.06);
    const y = u * 0.03 + rnd() * (height - u * 0.19);
    let ok = true;
    for (let b = 0; b < bands.length; b++) {
      if (x > bands[b][0] && x < bands[b][1]) ok = false;
    }
    if (!ok) continue;
    if (Math.hypot(x - cx, y - cy) < orbitR + u * 0.07) continue;
    for (let s = 0; s < stars.length; s++) {
      if (Math.hypot(x - stars[s].x, y - stars[s].y) < u * 0.055) { ok = false; break; }
    }
    if (!ok) continue;
    const sparkle = rnd() < 0.35;
    stars.push({
      x: x,
      y: y,
      sparkle: sparkle,
      r: sparkle ? u * (0.010 + rnd() * 0.008) : u * (0.0022 + rnd() * 0.002),
      ph: rnd() * TAU,
      k: 1 + Math.floor(rnd() * 2),
      dim: x > u * 0.12 && x < width * 0.53 ? 0.6 : 1
    });
  }

  // Skyline: baris jauh dan baris dekat (berdampingan, tidak saling menimpa)
  const far = [];
  let fx = -u * 0.02;
  let fi = 0;
  while (fx < width + u * 0.02) {
    const w = u * (0.06 + rnd() * 0.05);
    const h = u * (0.055 + rnd() * 0.06);
    far.push({ x: fx, w: w, h: h, tone: fi % 2 });
    fx += w;
    fi++;
  }

  const near = [];
  const winGroups = [[], [], []];
  const pitchX = u * 0.0145;
  const pitchY = u * 0.017;
  const winW = u * 0.0075;
  const winH = u * 0.0088;
  let nx = -u * 0.01;
  let ni = 0;
  while (nx < width + u * 0.01) {
    const w = u * (0.05 + rnd() * 0.04);
    const h = u * (0.035 + rnd() * 0.045);
    const top = height - h;
    const roof = rnd() < 0.45;
    near.push({ x: nx, w: w, h: h, tone: ni % 2, roof: roof });

    const cols = Math.max(1, Math.floor((w - u * 0.02 + (pitchX - winW)) / pitchX));
    const rows = Math.max(1, Math.floor((h - u * 0.032 + (pitchY - winH)) / pitchY));
    const gridW = cols * pitchX - (pitchX - winW);
    const gx0 = nx + (w - gridW) / 2;
    const gy0 = top + u * 0.012;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        if (rnd() < 0.45) {
          const g = Math.floor(rnd() * 3);
          winGroups[g].push(gx0 + c * pitchX, gy0 + r * pitchY);
        }
      }
    }
    nx += w;
    ni++;
  }

  return {
    key: width + 'x' + height,
    u: u, R: R, cx: cx, cy: cy, orbitR: orbitR,
    pieces: pieces, stars: stars,
    far: far, near: near, winGroups: winGroups,
    winW: winW, winH: winH,
    skylineTop: skylineTop, confettiMargin: confettiMargin
  };
}

function drawSparkle(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.3;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
}

function drawHand(ctx, len, tail, wBase, wTip) {
  ctx.beginPath();
  ctx.moveTo(-wBase / 2, tail);
  ctx.lineTo(-wTip / 2, -len);
  ctx.arc(0, -len, wTip / 2, Math.PI, 0, false);
  ctx.lineTo(wBase / 2, tail);
  ctx.arc(0, tail, wBase / 2, 0, Math.PI, false);
  ctx.closePath();
  ctx.fill();
}

function drawBackground(ctx, width, height) {
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#060A28');
  g.addColorStop(0.55, '#171458');
  g.addColorStop(1, '#4B2386');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawStars(ctx, S, p) {
  for (let i = 0; i < S.stars.length; i++) {
    const s = S.stars[i];
    const tw = 0.5 + 0.5 * Math.sin(TAU * s.k * p + s.ph);
    ctx.globalAlpha = (0.45 + 0.55 * tw) * s.dim;
    if (s.sparkle) {
      ctx.fillStyle = '#FFF1CF';
      drawSparkle(ctx, s.x, s.y, s.r * (0.84 + 0.16 * tw));
    } else {
      ctx.fillStyle = '#D6D0FF';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, TAU);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
}

function drawSkyline(ctx, S, width, height, p) {
  const u = S.u;
  const farColors = ['#2B1E66', '#33256F'];
  const nearColors = ['#14113F', '#1B174A'];

  for (let i = 0; i < S.far.length; i++) {
    const b = S.far[i];
    ctx.fillStyle = farColors[b.tone];
    ctx.fillRect(b.x, height - b.h, b.w, b.h);
  }

  for (let i = 0; i < S.near.length; i++) {
    const b = S.near[i];
    ctx.fillStyle = nearColors[b.tone];
    ctx.fillRect(b.x, height - b.h, b.w, b.h);
    if (b.roof) {
      const rw = b.w * 0.4;
      ctx.fillRect(b.x + (b.w - rw) / 2, height - b.h - u * 0.012, rw, u * 0.012);
    }
  }

  ctx.fillStyle = '#090726';
  ctx.fillRect(0, height - u * 0.01, width, u * 0.01);

  const ks = [1, 2, 1];
  const phs = [0, 2.1, 4.2];
  ctx.fillStyle = '#FFD36B';
  for (let g = 0; g < 3; g++) {
    const arr = S.winGroups[g];
    ctx.globalAlpha = 0.72 + 0.28 * Math.sin(TAU * ks[g] * p + phs[g]);
    ctx.beginPath();
    for (let i = 0; i < arr.length; i += 2) ctx.rect(arr[i], arr[i + 1], S.winW, S.winH);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawOrbitDots(ctx, S, p) {
  const u = S.u;
  const rot = -TAU * p;
  for (let i = 0; i < 24; i++) {
    const a = rot + (i * TAU) / 24 - Math.PI / 2;
    const big = i % 2 === 0;
    ctx.fillStyle = big ? '#F2C14E' : '#FFE7A3';
    ctx.beginPath();
    ctx.arc(S.cx + Math.cos(a) * S.orbitR, S.cy + Math.sin(a) * S.orbitR, big ? u * 0.0085 : u * 0.0042, 0, TAU);
    ctx.fill();
  }
}

function drawClock(ctx, S, p, bump) {
  const cx = S.cx, cy = S.cy, R = S.R;
  const NAVY = '#17154A';
  const MAGENTA = '#E0287D';

  // Bayangan flat (tanpa blur)
  ctx.fillStyle = 'rgba(3,4,22,0.30)';
  ctx.beginPath();
  ctx.arc(cx + R * 0.035, cy + R * 0.05, R, 0, TAU);
  ctx.fill();

  // Bezel emas dua nada
  ctx.fillStyle = '#F2C14E';
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#E0A933';
  ctx.beginPath();
  ctx.arc(cx, cy, R, -Math.PI * 0.25, Math.PI * 0.75);
  ctx.closePath();
  ctx.fill();

  // Titik dekor bezel
  ctx.fillStyle = '#B7801F';
  for (let i = 0; i < 12; i++) {
    const a = (i * TAU) / 12 - Math.PI / 2;
    ctx.beginPath();
    ctx.arc(cx + Math.cos(a) * R * 0.96, cy + Math.sin(a) * R * 0.96, R * 0.013, 0, TAU);
    ctx.fill();
  }

  // Track navy
  ctx.fillStyle = NAVY;
  ctx.beginPath();
  ctx.arc(cx, cy, R * 0.92, 0, TAU);
  ctx.fill();

  // Busur countdown mengikuti jarum menit (panjang tetap, seamless)
  const handA = TAU * p - Math.PI / 2;
  const arcLen = (55 * Math.PI) / 180;
  const capA = (R * 0.025) / (R * 0.89);
  const arcStart = handA - arcLen;
  const arcEnd = handA - capA;
  let arcStyle = 'rgba(224,40,125,0.9)';
  if (typeof ctx.createConicGradient === 'function') {
    const cg = ctx.createConicGradient(arcStart, cx, cy);
    cg.addColorStop(0, 'rgba(224,40,125,0)');
    cg.addColorStop(arcLen / TAU, 'rgba(224,40,125,1)');
    cg.addColorStop(1, 'rgba(224,40,125,1)');
    arcStyle = cg;
  }
  ctx.strokeStyle = arcStyle;
  ctx.lineWidth = R * 0.05;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(cx, cy, R * 0.89, arcStart, arcEnd);
  ctx.stroke();

  // Wajah jam
  ctx.fillStyle = '#F7F1E5';
  ctx.beginPath();
  ctx.arc(cx, cy, R * 0.86, 0, TAU);
  ctx.fill();

  // Tick menit
  ctx.lineCap = 'butt';
  ctx.strokeStyle = '#8A86B3';
  ctx.lineWidth = R * 0.0065;
  ctx.beginPath();
  for (let i = 0; i < 60; i++) {
    if (i % 5 === 0) continue;
    const a = (i * TAU) / 60 - Math.PI / 2;
    ctx.moveTo(cx + Math.cos(a) * R * 0.805, cy + Math.sin(a) * R * 0.805);
    ctx.lineTo(cx + Math.cos(a) * R * 0.84, cy + Math.sin(a) * R * 0.84);
  }
  ctx.stroke();

  // Tick jam
  ctx.strokeStyle = NAVY;
  ctx.lineWidth = R * 0.016;
  ctx.beginPath();
  for (let i = 1; i < 12; i++) {
    const a = (i * TAU) / 12 - Math.PI / 2;
    ctx.moveTo(cx + Math.cos(a) * R * 0.76, cy + Math.sin(a) * R * 0.76);
    ctx.lineTo(cx + Math.cos(a) * R * 0.84, cy + Math.sin(a) * R * 0.84);
  }
  ctx.stroke();

  // Tick 12 (aksen magenta)
  ctx.strokeStyle = MAGENTA;
  ctx.lineWidth = R * 0.022;
  ctx.beginPath();
  ctx.moveTo(cx, cy - R * 0.74);
  ctx.lineTo(cx, cy - R * 0.84);
  ctx.stroke();

  // Angka jam
  const fontSize = R * 0.1;
  ctx.font = '700 ' + fontSize + 'px "Helvetica Neue", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (let n = 1; n <= 12; n++) {
    const a = (n * TAU) / 12 - Math.PI / 2;
    const s = n === 12 ? 1 + 0.14 * bump : 1;
    ctx.save();
    ctx.translate(cx + Math.cos(a) * R * 0.64, cy + Math.sin(a) * R * 0.64);
    ctx.scale(s, s);
    ctx.fillStyle = n === 12 ? MAGENTA : NAVY;
    ctx.fillText(String(n), 0, fontSize * 0.04);
    ctx.restore();
  }

  // Jarum jam (posisi tetap menjelang tengah malam)
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate((-2.5 * Math.PI) / 180);
  ctx.fillStyle = NAVY;
  drawHand(ctx, R * 0.34, R * 0.08, R * 0.05, R * 0.034);
  ctx.restore();

  // Jarum menit (1 putaran penuh per loop)
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(TAU * p);
  ctx.fillStyle = NAVY;
  drawHand(ctx, R * 0.5, R * 0.1, R * 0.034, R * 0.018);
  ctx.restore();

  // Hub
  ctx.fillStyle = '#F2C14E';
  ctx.beginPath();
  ctx.arc(cx, cy, R * 0.055, 0, TAU);
  ctx.fill();
  ctx.fillStyle = MAGENTA;
  ctx.beginPath();
  ctx.arc(cx, cy, R * 0.022, 0, TAU);
  ctx.fill();
}

function drawConfetti(ctx, S, height, p) {
  const u = S.u;
  const m = S.confettiMargin;
  const yEnd = S.skylineTop;
  const span = yEnd + m;
  const fade = u * 0.08;
  const colors = ['#F2C14E', '#E0287D', '#FFE7A3', '#B3195F'];

  for (let i = 0; i < S.pieces.length; i++) {
    const c = S.pieces[i];
    const prog = (c.phase + c.cyc * p) % 1;
    const y = -m + prog * span;
    const alpha = clamp01((yEnd - y) / fade);
    if (alpha <= 0) continue;

    const x = c.x + Math.sin(TAU * c.sk * p + c.sph) * c.amp;
    const rot = c.rot + TAU * c.rc * c.dir * p;
    const flip = 0.68 + 0.32 * Math.cos(TAU * c.fc * p + c.fph);

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.scale(1, flip);
    ctx.fillStyle = colors[c.col];
    if (c.type === 0) {
      ctx.fillRect(-u * 0.0065, -u * 0.0045, u * 0.013, u * 0.009);
    } else if (c.type === 1) {
      ctx.fillRect(-u * 0.0025, -u * 0.011, u * 0.005, u * 0.022);
    } else if (c.type === 2) {
      ctx.beginPath();
      ctx.arc(0, 0, u * 0.0062, 0, TAU);
      ctx.fill();
    } else {
      const r = u * 0.0087;
      ctx.beginPath();
      ctx.moveTo(0, -r);
      ctx.lineTo(r * 0.866, r * 0.5);
      ctx.lineTo(-r * 0.866, r * 0.5);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;

  // Denyut angka 12 saat jarum menit melewati tengah malam (simetris di titik loop)
  const dEdge = Math.min(loopT, duration - loopT);
  const bump = Math.exp(-(dEdge * dEdge) / (2 * 0.45 * 0.45));

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawBackground(ctx, width, height);
  drawStars(ctx, S, p);
  drawSkyline(ctx, S, width, height, p);
  drawOrbitDots(ctx, S, p);
  drawClock(ctx, S, p, bump);
  drawConfetti(ctx, S, height, p);

  ctx.restore();
}

// KONSEP 2 — FIREWORKS OVER CITY SKYLINE
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function smooth(v) {
  v = clamp01(v);
  return v * v * (3 - 2 * v);
}

function easeOutCubic(v) {
  const k = 1 - clamp01(v);
  return 1 - k * k * k;
}

function easeOutQuad(v) {
  const k = 1 - clamp01(v);
  return 1 - k * k;
}

function buildLayer(rnd, width, u, cfg) {
  const blds = [];
  const wins = [[], [], []];
  const waterY = cfg.waterY;
  let x = -u * 0.06;
  let i = 0;
  while (x < width + u * 0.06) {
    const w = u * (cfg.wMin + rnd() * (cfg.wMax - cfg.wMin));
    const h = u * (cfg.hMin + rnd() * (cfg.hMax - cfg.hMin));
    const r = rnd();
    let type = 0;
    if (r < cfg.pStep) type = 1;
    else if (r < cfg.pStep + cfg.pSpire) type = 2;
    const bodyH = type === 1 ? h * 0.65 : h;
    const spire = type === 2 ? u * 0.045 : 0;
    blds.push({ x: x, w: w, h: h, bodyH: bodyH, type: type, spire: spire, tone: i % 2 });

    if (cfg.win) {
      const pX = u * cfg.pitchX;
      const pY = u * cfg.pitchY;
      const wW = u * cfg.winW;
      const wH = u * cfg.winH;
      const cols = Math.max(1, Math.floor((w - u * 0.016 + (pX - wW)) / pX));
      const rows = Math.max(0, Math.floor((bodyH - u * 0.032 + (pY - wH)) / pY));
      const gridW = cols * pX - (pX - wW);
      const gx0 = x + (w - gridW) / 2;
      const gy0 = waterY - bodyH + u * 0.012;
      for (let rr = 0; rr < rows; rr++) {
        for (let c = 0; c < cols; c++) {
          if (rnd() < cfg.lit) {
            const g = Math.floor(rnd() * 3);
            wins[g].push(gx0 + c * pX, gy0 + rr * pY);
          }
        }
      }
    }
    x += w;
    i++;
  }
  return { blds: blds, wins: wins, winW: u * (cfg.winW || 0), winH: u * (cfg.winH || 0) };
}

function buildScene(width, height) {
  const u = Math.min(width, height);
  const rnd = rng(20270102);
  const waterY = height * 0.8;
  const duration = 20;

  const palettes = [
    ['#F2C14E', '#E8318A'],
    ['#4FD1E8', '#A99BFF'],
    ['#FF7A59', '#F2C14E'],
    ['#E8318A', '#4FD1E8'],
    ['#F2C14E', '#4FD1E8'],
    ['#A99BFF', '#FF7A59']
  ];

  // Posisi ledakan: kiri/kanan copy space, bergantian (L, R, L, R, L, R)
  const specs = [
    { side: 'L', a: 0.26, y: 0.30, r: 0.135 },
    { side: 'R', a: 0.28, y: 0.27, r: 0.130 },
    { side: 'L', a: 0.33, y: 0.39, r: 0.125 },
    { side: 'R', a: 0.34, y: 0.37, r: 0.130 },
    { side: 'L', a: 0.20, y: 0.25, r: 0.120 },
    { side: 'R', a: 0.20, y: 0.31, r: 0.125 }
  ];
  const spacing = duration / specs.length;
  const bursts = specs.map(function (s, i) {
    return {
      x: s.side === 'L' ? u * s.a : width - u * s.a,
      y: u * s.y,
      r: u * s.r,
      start: i * spacing + 1.0,
      pal: palettes[i],
      rot: i * 0.37
    };
  });

  // Bintang (hindari area ledakan, jalur roket, dan skyline)
  const stars = [];
  let tries = 0;
  while (stars.length < 70 && tries < 6000) {
    tries++;
    const x = u * 0.03 + rnd() * (width - u * 0.06);
    const y = u * 0.03 + rnd() * (u * 0.53);
    let ok = true;
    for (let b = 0; b < bursts.length; b++) {
      const bb = bursts[b];
      if (Math.hypot(x - bb.x, y - bb.y) < bb.r * 1.1 + u * 0.05) { ok = false; break; }
      if (Math.abs(x - bb.x) < u * 0.035 && y > bb.y) { ok = false; break; }
    }
    if (!ok) continue;
    for (let s = 0; s < stars.length; s++) {
      if (Math.hypot(x - stars[s].x, y - stars[s].y) < u * 0.055) { ok = false; break; }
    }
    if (!ok) continue;
    const sparkle = rnd() < 0.3;
    const inCopy = Math.abs(x - width / 2) < u * 0.34 && y < u * 0.45;
    stars.push({
      x: x,
      y: y,
      sparkle: sparkle,
      r: sparkle ? u * (0.009 + rnd() * 0.007) : u * (0.0022 + rnd() * 0.002),
      ph: rnd() * TAU,
      k: 1 + Math.floor(rnd() * 2),
      dim: inCopy ? 0.5 : 1
    });
  }

  // Tiga lapisan skyline
  const far = buildLayer(rnd, width, u, {
    waterY: waterY, wMin: 0.07, wMax: 0.13, hMin: 0.10, hMax: 0.22,
    pStep: 0.3, pSpire: 0, win: false
  });
  const mid = buildLayer(rnd, width, u, {
    waterY: waterY, wMin: 0.06, wMax: 0.11, hMin: 0.07, hMax: 0.16,
    pStep: 0.3, pSpire: 0, win: true,
    pitchX: 0.011, pitchY: 0.013, winW: 0.0055, winH: 0.0066, lit: 0.35
  });
  const near = buildLayer(rnd, width, u, {
    waterY: waterY, wMin: 0.05, wMax: 0.09, hMin: 0.04, hMax: 0.11,
    pStep: 0.2, pSpire: 0.15, win: true,
    pitchX: 0.0145, pitchY: 0.017, winW: 0.0075, winH: 0.0088, lit: 0.45
  });

  // Garis riak air (jarak antarbatang selalu lebih besar dari amplitudo geser)
  const ripples = [];
  for (let row = 0; row < 8; row++) {
    let x = rnd() * u * 0.1;
    const y = waterY + u * (0.032 + 0.022 * row);
    const k = 1 + (row % 2);
    while (x < width) {
      const len = u * (0.05 + rnd() * 0.13) * (0.6 + 0.06 * row);
      ripples.push({ x: x, y: y, len: len, k: k, ph: rnd() * TAU });
      x += len + u * (0.10 + rnd() * 0.18);
    }
  }

  return {
    key: width + 'x' + height,
    u: u, waterY: waterY,
    bursts: bursts, stars: stars,
    far: far, mid: mid, near: near,
    ripples: ripples,
    rocketDur: 1.5, burstDur: 3.3
  };
}

function drawSparkle(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.3;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
}

function drawStars(ctx, S, p) {
  for (let i = 0; i < S.stars.length; i++) {
    const s = S.stars[i];
    const tw = 0.5 + 0.5 * Math.sin(TAU * s.k * p + s.ph);
    ctx.globalAlpha = (0.45 + 0.55 * tw) * s.dim;
    if (s.sparkle) {
      ctx.fillStyle = '#FFF1CF';
      drawSparkle(ctx, s.x, s.y, s.r * (0.84 + 0.16 * tw));
    } else {
      ctx.fillStyle = '#D6D0FF';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, TAU);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
}

function drawRocket(ctx, S, b, lt) {
  const u = S.u;
  const pr = clamp01(lt / S.rocketDur);
  const y0 = S.waterY;
  const headY = y0 + (b.y - y0) * easeOutQuad(pr);
  const tailY = y0 + (b.y - y0) * easeOutQuad(Math.max(0, pr - 0.2));
  if (Math.abs(headY - tailY) < 0.5) return;
  const a = 1 - smooth((pr - 0.92) / 0.08);
  const g = ctx.createLinearGradient(b.x, tailY, b.x, headY);
  g.addColorStop(0, 'rgba(255,241,207,0)');
  g.addColorStop(1, 'rgba(255,241,207,' + a.toFixed(3) + ')');
  ctx.strokeStyle = g;
  ctx.lineWidth = u * 0.0045;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(b.x, tailY);
  ctx.lineTo(b.x, headY);
  ctx.stroke();
}

function drawBurst(ctx, S, b, prog) {
  const u = S.u;
  const ia = smooth(prog / 0.07);
  const fa = 1 - smooth((prog - 0.5) / 0.5);
  const alpha = ia * fa;
  if (alpha <= 0.001) return;

  const e = easeOutCubic(prog);
  const eT = easeOutCubic(Math.max(0, prog - 0.1));
  const dropH = b.r * 0.1 * prog * prog;
  const pT = Math.max(0, prog - 0.1);
  const dropT = b.r * 0.1 * pT * pT;

  const rings = [
    { n: 32, start: 0, step: 2, rf: 1.0, color: b.pal[0], lw: 0.0048 },
    { n: 16, start: 1, step: 4, rf: 0.66, color: b.pal[1], lw: 0.0042 },
    { n: 8, start: 3, step: 8, rf: 0.36, color: '#FFF1CF', lw: 0.0036 }
  ];

  ctx.globalAlpha = alpha;
  ctx.lineCap = 'round';
  for (let q = 0; q < rings.length; q++) {
    const rg = rings[q];
    ctx.strokeStyle = rg.color;
    ctx.lineWidth = u * rg.lw * (0.55 + 0.45 * alpha);
    ctx.beginPath();
    for (let k = 0; k < rg.n; k++) {
      const ang = b.rot + ((rg.start + k * rg.step) * TAU) / 64;
      const ca = Math.cos(ang);
      const sa = Math.sin(ang);
      const rh = rg.rf * b.r * e;
      const rt = rg.rf * b.r * eT;
      ctx.moveTo(b.x + ca * rt, b.y + sa * rt + dropT);
      ctx.lineTo(b.x + ca * rh, b.y + sa * rh + dropH);
    }
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

function drawFireworks(ctx, S, loopT, duration) {
  for (let i = 0; i < S.bursts.length; i++) {
    const b = S.bursts[i];
    const lt = (((loopT - b.start) % duration) + duration) % duration;
    if (lt < S.rocketDur) {
      drawRocket(ctx, S, b, lt);
    } else if (lt < S.rocketDur + S.burstDur) {
      drawBurst(ctx, S, b, (lt - S.rocketDur) / S.burstDur);
    }
  }
}

function drawLayer(ctx, S, L, ox, cols, winColor, p, winAlphaMul) {
  const waterY = S.waterY;
  const u = S.u;
  for (let i = 0; i < L.blds.length; i++) {
    const b = L.blds[i];
    const bx = b.x + ox;
    ctx.fillStyle = cols[b.tone];
    ctx.fillRect(bx, waterY - b.bodyH, b.w, b.bodyH);
    if (b.type === 1) {
      const tw = b.w * 0.62;
      ctx.fillRect(bx + (b.w - tw) / 2, waterY - b.h, tw, b.h - b.bodyH);
    } else if (b.type === 2) {
      const sw = b.w * 0.2;
      ctx.beginPath();
      ctx.moveTo(bx + b.w / 2 - sw / 2, waterY - b.bodyH);
      ctx.lineTo(bx + b.w / 2, waterY - b.bodyH - b.spire);
      ctx.lineTo(bx + b.w / 2 + sw / 2, waterY - b.bodyH);
      ctx.closePath();
      ctx.fill();
    }
  }
  if (!L.winW) return;
  const ks = [1, 2, 1];
  const phs = [0, 2.1, 4.2];
  ctx.fillStyle = winColor;
  for (let g = 0; g < 3; g++) {
    const arr = L.wins[g];
    ctx.globalAlpha = (0.72 + 0.28 * Math.sin(TAU * ks[g] * p + phs[g])) * winAlphaMul;
    ctx.beginPath();
    for (let i = 0; i < arr.length; i += 2) ctx.rect(arr[i] + ox, arr[i + 1], L.winW, L.winH);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawSkyline(ctx, S, p, mirror) {
  const u = S.u;
  const oxFar = u * 0.004 * Math.cos(TAU * p);
  const oxMid = u * 0.008 * Math.cos(TAU * p);
  const oxNear = u * 0.014 * Math.cos(TAU * p);
  const colsFar = mirror ? ['#2D2370', '#33297A'] : ['#2A2370', '#312878'];
  const colsMid = mirror ? ['#231B5E', '#292165'] : ['#1E1957', '#241E60'];
  const colsNear = mirror ? ['#171248', '#1C1752'] : ['#120F3D', '#18144A'];
  const wa = mirror ? 0.5 : 1;
  drawLayer(ctx, S, S.far, oxFar, colsFar, '#000000', p, 0);
  drawLayer(ctx, S, S.mid, oxMid, colsMid, mirror ? '#B8903F' : '#E0B04A', p, wa);
  drawLayer(ctx, S, S.near, oxNear, colsNear, mirror ? '#C9A54E' : '#FFD36B', p, wa);
}

function drawWater(ctx, S, width, height, p) {
  const u = S.u;
  const waterY = S.waterY;

  // Pantulan skyline (dibatasi area air, tinggi dan gelap)
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, waterY, width, height - waterY);
  ctx.clip();
  ctx.translate(0, 2 * waterY);
  ctx.scale(1, -1);
  drawSkyline(ctx, S, p, true);
  ctx.restore();

  // Pudar kedalaman air
  const fg = ctx.createLinearGradient(0, waterY, 0, height);
  fg.addColorStop(0, 'rgba(9,11,48,0)');
  fg.addColorStop(1, 'rgba(9,11,48,0.9)');
  ctx.fillStyle = fg;
  ctx.fillRect(0, waterY, width, height - waterY);

  // Garis riak
  ctx.fillStyle = 'rgba(214,208,255,0.14)';
  ctx.beginPath();
  for (let i = 0; i < S.ripples.length; i++) {
    const r = S.ripples[i];
    const x = r.x + Math.sin(TAU * r.k * p + r.ph) * u * 0.01;
    ctx.rect(x, r.y, r.len, u * 0.0035);
  }
  ctx.fill();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;
  const waterY = S.waterY;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  // Langit
  const sky = ctx.createLinearGradient(0, 0, 0, waterY);
  sky.addColorStop(0, '#050824');
  sky.addColorStop(0.5, '#13134F');
  sky.addColorStop(1, '#5A2A8C');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, width, waterY);

  // Air
  const wg = ctx.createLinearGradient(0, waterY, 0, height);
  wg.addColorStop(0, '#3A1D68');
  wg.addColorStop(1, '#090B30');
  ctx.fillStyle = wg;
  ctx.fillRect(0, waterY, width, height - waterY);

  drawStars(ctx, S, p);
  drawFireworks(ctx, S, loopT, duration);
  drawSkyline(ctx, S, p, false);
  drawWater(ctx, S, width, height, p);

  // Dermaga tipis di garis air
  ctx.fillStyle = '#0A0826';
  ctx.fillRect(0, waterY - minSide * 0.006, width, minSide * 0.012);

  ctx.restore();
}

// KONSEP 3 — CHAMPAGNE TOAST CELEBRATION
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function smooth(v) {
  v = clamp01(v);
  return v * v * (3 - 2 * v);
}

function lerp(a, b, f) {
  return a + (b - a) * f;
}

function buildScene(width, height) {
  const u = Math.min(width, height);
  const rnd = rng(20270103);
  const duration = 20;

  // Geometri gelas flute (koordinat lokal berpusat di pivot, y negatif = ke atas)
  const G = {
    wR: 0.074 * u, wB: 0.030 * u,
    yT: -0.27 * u, yB: -0.08 * u, rb: 0.02 * u,
    wt: 0.004 * u, yL: -0.21 * u,
    stemW: 0.007 * u, stemBot: 0.08 * u,
    footY: 0.083 * u, footRx: 0.046 * u, footRy: 0.0085 * u
  };
  const thC = (8 * Math.PI) / 180;
  const th0 = (-1.5 * Math.PI) / 180;
  const gap = 0.002 * u;
  // Jarak pivot dihitung agar sudut rim bertemu tepat di sumbu tengah (hanya menyentuh, tidak menembus)
  const d = (G.wR / 2) * Math.cos(thC) + -G.yT * Math.sin(thC) + gap / 2;

  const cx = width * 0.27;
  const py = height * 0.72;
  const contactY = py + (G.wR / 2) * Math.sin(thC) + G.yT * Math.cos(thC);

  // Gelembung di dalam gelas (3 jalur x 3 gelembung per gelas)
  const laneXs = [-0.008 * u, 0, 0.008 * u];
  const laneCyc = [3, 4, 5];
  const glassBubbles = [[], []];
  for (let g = 0; g < 2; g++) {
    for (let li = 0; li < 3; li++) {
      const off = rnd();
      for (let j = 0; j < 3; j++) {
        glassBubbles[g].push({
          x: laneXs[li],
          phase: (j + off) / 3,
          cyc: laneCyc[li],
          r: u * (0.0022 + rnd() * 0.0006),
          sk: 1 + ((li + j) % 2),
          ph: rnd() * TAU
        });
      }
    }
  }

  // Gelembung ambient (jalur vertikal di kiri dan kanan gelas, tidak melewati gelas)
  const ambX = [cx - 0.30 * u, cx - 0.22 * u, cx + 0.22 * u, cx + 0.30 * u];
  const amb = [];
  ambX.forEach(function (x, li) {
    const off = rnd();
    const n = 8;
    for (let j = 0; j < n; j++) {
      amb.push({
        x: x,
        phase: (j + off) / n,
        cyc: li % 2 === 0 ? 2 : 1,
        r: u * (0.006 + rnd() * 0.008),
        amp: u * 0.005,
        sk: 1 + (j % 2),
        ph: rnd() * TAU
      });
    }
  });

  // Bokeh geometris (jalur di sisi kanan, jarak antarjalur lebih besar dari diameter)
  const bokeh = [];
  const bokehColors = ['#F2C14E', '#E8A6A0', '#FFF1CF'];
  for (let li = 0; li < 5; li++) {
    const x = width * (0.57 + 0.085 * li);
    const off = rnd();
    const n = 3;
    for (let j = 0; j < n; j++) {
      bokeh.push({
        x: x,
        phase: (j + off) / n,
        cyc: li % 2 === 0 ? 1 : 2,
        r: u * (0.035 + rnd() * 0.025),
        hex: (j + li) % 2 === 0,
        col: bokehColors[(j + li) % 3],
        a: 0.06 + rnd() * 0.03,
        rot: rnd() * TAU,
        amp: u * 0.006,
        sph: rnd() * TAU
      });
    }
  }

  // Kilau emas di atas gelas (hindari zona percikan dan jalur gelembung)
  const sparkles = [];
  let tries = 0;
  while (sparkles.length < 7 && tries < 4000) {
    tries++;
    const x = cx - 0.2 * u + rnd() * 0.4 * u;
    const y = 0.07 * u + rnd() * 0.23 * u;
    let ok = true;
    for (let s = 0; s < sparkles.length; s++) {
      if (Math.hypot(x - sparkles[s].x, y - sparkles[s].y) < 0.08 * u) { ok = false; break; }
    }
    if (!ok) continue;
    sparkles.push({
      x: x,
      y: y,
      r: u * (0.010 + rnd() * 0.008),
      k: 1 + Math.floor(rnd() * 2),
      ph: rnd() * TAU,
      col: sparkles.length % 3 === 0 ? '#FFF1CF' : '#F7D774'
    });
  }

  return {
    key: width + 'x' + height,
    u: u, G: G, duration: duration,
    thC: thC, th0: th0, d: d,
    cx: cx, py: py, contactY: contactY,
    glassBubbles: glassBubbles, amb: amb, bokeh: bokeh, sparkles: sparkles
  };
}

function drawSparkle(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.3;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
}

function bowlPath(ctx, wr, wb, yT, yB, rb) {
  ctx.beginPath();
  ctx.moveTo(-wr / 2, yT);
  ctx.lineTo(wr / 2, yT);
  ctx.lineTo(wb / 2, yB);
  ctx.quadraticCurveTo(0, yB + rb, -wb / 2, yB);
  ctx.closePath();
}

function innerHalfWidth(G, y) {
  const yb = G.yB - G.wt * 0.25;
  const f = clamp01((yb - y) / (yb - G.yT));
  return lerp((G.wB - 1.6 * G.wt) / 2, (G.wR - 2 * G.wt) / 2, f);
}

function drawBackground(ctx, width, height) {
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#120E0B');
  g.addColorStop(0.55, '#2A1E15');
  g.addColorStop(1, '#4B3520');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawBokeh(ctx, S, height, p) {
  const u = S.u;
  const m = u * 0.07;
  const span = height + 2 * m;
  for (let i = 0; i < S.bokeh.length; i++) {
    const b = S.bokeh[i];
    const prog = (b.phase + b.cyc * p) % 1;
    const y = height + m - prog * span;
    const x = b.x + Math.sin(TAU * p + b.sph) * b.amp;
    ctx.globalAlpha = b.a;
    ctx.fillStyle = b.col;
    ctx.beginPath();
    if (b.hex) {
      const rot = b.rot + (TAU / 6) * p;
      for (let k = 0; k < 6; k++) {
        const a = rot + (k * TAU) / 6;
        const px = x + Math.cos(a) * b.r;
        const py = y + Math.sin(a) * b.r;
        if (k === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.closePath();
    } else {
      ctx.arc(x, y, b.r, 0, TAU);
    }
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawSparkles(ctx, S, p) {
  for (let i = 0; i < S.sparkles.length; i++) {
    const s = S.sparkles[i];
    const tw = 0.5 + 0.5 * Math.sin(TAU * s.k * p + s.ph);
    ctx.globalAlpha = 0.4 + 0.6 * tw;
    ctx.fillStyle = s.col;
    drawSparkle(ctx, s.x, s.y, s.r * (0.82 + 0.18 * tw));
  }
  ctx.globalAlpha = 1;
}

function drawAmbientBubbles(ctx, S, height, p) {
  const u = S.u;
  const yStart = height + u * 0.04;
  const yEnd = -u * 0.04;
  ctx.lineWidth = u * 0.0025;
  for (let i = 0; i < S.amb.length; i++) {
    const b = S.amb[i];
    const prog = (b.phase + b.cyc * p) % 1;
    const y = yStart + (yEnd - yStart) * prog;
    const x = b.x + Math.sin(TAU * b.sk * p + b.ph) * b.amp;
    const r = b.r * (0.85 + 0.3 * prog);
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fillStyle = 'rgba(247,215,116,0.12)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,241,207,0.55)';
    ctx.stroke();
  }
}

function drawGlass(ctx, S, theta, p, g, px, py, mirror) {
  const u = S.u;
  const G = S.G;
  const TINT = 'rgba(255,248,230,0.16)';
  const LINE = 'rgba(255,241,207,0.9)';

  ctx.save();
  ctx.translate(px, py);
  if (mirror) ctx.scale(-1, 1);
  ctx.rotate(theta);

  // Badan mangkuk (tint kaca)
  bowlPath(ctx, G.wR, G.wB, G.yT, G.yB, G.rb);
  ctx.fillStyle = TINT;
  ctx.fill();

  // Cairan champagne (permukaan tetap horizontal terhadap dunia)
  ctx.save();
  bowlPath(ctx, G.wR - 2 * G.wt, G.wB - 1.6 * G.wt, G.yT, G.yB - G.wt * 0.25, G.rb - G.wt * 0.75);
  ctx.clip();

  ctx.save();
  ctx.translate(0, G.yL);
  ctx.rotate(-theta);
  const big = u * 0.2;
  ctx.fillStyle = '#EFCB72';
  ctx.fillRect(-big, 0, 2 * big, big);
  ctx.fillStyle = '#E0B04E';
  ctx.fillRect(-big, u * 0.075, 2 * big, big);
  ctx.fillStyle = '#FFF4D6';
  ctx.fillRect(-big, -u * 0.009, 2 * big, u * 0.009);
  ctx.restore();

  // Gelembung dalam cairan
  const y1 = -0.10 * u;
  const y2 = -0.205 * u;
  const arr = S.glassBubbles[g];
  ctx.fillStyle = '#FFF8E6';
  for (let i = 0; i < arr.length; i++) {
    const b = arr[i];
    const prog = (b.phase + b.cyc * p) % 1;
    const a = smooth(prog / 0.15) * (1 - smooth((prog - 0.75) / 0.25));
    if (a <= 0.01) continue;
    ctx.globalAlpha = 0.8 * a;
    ctx.beginPath();
    ctx.arc(b.x + Math.sin(TAU * b.sk * p + b.ph) * u * 0.001, lerp(y1, y2, prog), b.r, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Highlight kaca (bagian atas dinding kiri)
  const hy1 = -0.255 * u;
  const hy2 = -0.17 * u;
  ctx.strokeStyle = 'rgba(255,255,255,0.38)';
  ctx.lineWidth = u * 0.0035;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-innerHalfWidth(G, hy1) + u * 0.0045, hy1);
  ctx.lineTo(-innerHalfWidth(G, hy2) + u * 0.0045, hy2);
  ctx.stroke();
  ctx.restore();

  // Outline mangkuk
  bowlPath(ctx, G.wR, G.wB, G.yT, G.yB, G.rb);
  ctx.strokeStyle = LINE;
  ctx.lineWidth = u * 0.0035;
  ctx.lineJoin = 'round';
  ctx.stroke();

  // Tangkai
  ctx.fillStyle = TINT;
  ctx.fillRect(-G.stemW / 2, -0.0695 * u, G.stemW, G.stemBot + 0.0695 * u);
  ctx.beginPath();
  ctx.moveTo(-G.stemW / 2, -0.0695 * u);
  ctx.lineTo(-G.stemW / 2, G.stemBot);
  ctx.moveTo(G.stemW / 2, -0.0695 * u);
  ctx.lineTo(G.stemW / 2, G.stemBot);
  ctx.stroke();

  // Cincin emas pada tangkai
  ctx.fillStyle = '#E8B84A';
  ctx.fillRect(-G.stemW / 2 - u * 0.001, -0.005 * u, G.stemW + u * 0.002, 0.006 * u);

  // Alas
  ctx.beginPath();
  ctx.ellipse(0, G.footY, G.footRx, G.footRy, 0, 0, TAU);
  ctx.fillStyle = TINT;
  ctx.fill();
  ctx.stroke();

  // Kilau di tepi luar rim (ikut berputar dengan gelas)
  const tw = 0.5 + 0.5 * Math.sin(TAU * 2 * p + g * 1.7);
  ctx.globalAlpha = 0.45 + 0.55 * tw;
  ctx.fillStyle = '#F7D774';
  drawSparkle(ctx, -G.wR / 2 - u * 0.02, G.yT - u * 0.013, u * 0.010 * (0.82 + 0.18 * tw));
  ctx.globalAlpha = 1;

  ctx.restore();
}

function drawDroplets(ctx, S, p) {
  const u = S.u;
  const c = (p * 4) % 1;
  if (c < 0.5) return;
  const tau = (c - 0.5) * (S.duration / 4);
  if (tau >= 0.9) return;
  const k = Math.floor(p * 4);
  const pc = (k + 0.5) / 4;
  const ox = S.cx;
  const oy = S.contactY + u * 0.005 * Math.sin(TAU * 2 * pc);
  const alpha = smooth(tau / 0.12) * (1 - smooth((tau - 0.5) / 0.4));
  if (alpha <= 0.005) return;
  const gr = u * 0.25;
  ctx.fillStyle = '#F7D774';
  ctx.globalAlpha = alpha;
  for (let i = 0; i < 8; i++) {
    const phi = ((50 + i * (80 / 7)) * Math.PI) / 180;
    const v = u * (i % 2 === 0 ? 0.16 : 0.22);
    const x = ox + v * Math.cos(phi) * tau;
    const y = oy - v * Math.sin(phi) * tau + 0.5 * gr * tau * tau;
    ctx.beginPath();
    ctx.arc(x, y, u * 0.004, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;

  // 4 kali bersulang per loop (siklus 5 detik); sentuhan tepat di c = 0.5
  const c = (p * 4) % 1;
  let A = 0;
  if (c >= 0.3 && c < 0.5) A = smooth((c - 0.3) / 0.2);
  else if (c >= 0.5 && c < 0.78) A = 1 - smooth((c - 0.5) / 0.28);
  const theta = S.th0 + (S.thC - S.th0) * A;

  // Kedua gelas mengambang naik-turun bersama (jarak relatif tidak berubah)
  const bob = minSide * 0.005 * Math.sin(TAU * 2 * p);
  const py = S.py + bob;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawBackground(ctx, width, height);
  drawBokeh(ctx, S, height, p);
  drawSparkles(ctx, S, p);
  drawAmbientBubbles(ctx, S, height, p);

  drawGlass(ctx, S, theta, p, 0, S.cx - S.d, py, false);
  drawGlass(ctx, S, theta, p, 1, S.cx + S.d, py, true);

  drawDroplets(ctx, S, p);

  ctx.restore();
}

// KONSEP 4 — ROTATING YEAR RIBBON RING
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildScene(width, height) {
  const u = Math.min(width, height);
  const rnd = rng(20270104);
  const cx = width / 2;
  const cy = height / 2;

  // Tiga cincin pita (radius pusat, setengah lebar maksimum, jumlah lobus, putaran per loop, arah)
  // Jarak antarcincin dijaga: tepi luar cincin i < tepi dalam cincin i+1
  const rings = [
    { r: 0.300 * u, H: 0.014 * u, n: 18, m: 3, dir: 1, A: '#F2C14E', B: '#B98320' },
    { r: 0.355 * u, H: 0.016 * u, n: 24, m: 3, dir: -1, A: '#EBB1A8', B: '#B8707A' },
    { r: 0.415 * u, H: 0.020 * u, n: 30, m: 3, dir: 1, A: '#F5CF6A', B: '#D98E94' }
  ];

  // Titik-titik pada celah antarcincin
  const gaps = [
    { r: 0.3265 * u, N: 36, m: 2, dir: -1 },
    { r: 0.383 * u, N: 48, m: 3, dir: 1 }
  ];

  // Cincin putus-putus latar (jumlah dash bilangan bulat agar seamless)
  const dashRings = [
    { r: 0.62 * u, N: 180, m: 6, dir: 1 },
    { r: 0.78 * u, N: 240, m: 5, dir: -1 }
  ];

  // Bintang latar (di luar zona cincin, jauh dari garis dash)
  const stars = [];
  let tries = 0;
  while (stars.length < 50 && tries < 8000) {
    tries++;
    const x = u * 0.03 + rnd() * (width - u * 0.06);
    const y = u * 0.03 + rnd() * (height - u * 0.06);
    const dist = Math.hypot(x - cx, y - cy);
    if (dist < 0.56 * u) continue;
    let ok = true;
    for (let k = 0; k < dashRings.length; k++) {
      if (Math.abs(dist - dashRings[k].r) < 0.03 * u) ok = false;
    }
    if (!ok) continue;
    for (let s = 0; s < stars.length; s++) {
      if (Math.hypot(x - stars[s].x, y - stars[s].y) < 0.06 * u) { ok = false; break; }
    }
    if (!ok) continue;
    const sparkle = rnd() < 0.35;
    stars.push({
      x: x,
      y: y,
      sparkle: sparkle,
      r: sparkle ? u * (0.009 + rnd() * 0.007) : u * (0.0022 + rnd() * 0.002),
      ph: rnd() * TAU,
      k: 1 + Math.floor(rnd() * 2)
    });
  }

  return {
    key: width + 'x' + height,
    u: u, cx: cx, cy: cy,
    rings: rings, gaps: gaps, dashRings: dashRings, stars: stars,
    orbitR: 0.467 * u, orbitN: 24
  };
}

function drawSparkle(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.3;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
}

// Easing sinusoidal periodik: kecepatan selalu positif dan kontinu, E(0)=0, E(1)=1
function ease(p) {
  return p + (0.35 * Math.sin(TAU * p)) / TAU;
}

function drawBackground(ctx, S, width, height) {
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#0A0E2A');
  g.addColorStop(0.55, '#171640');
  g.addColorStop(1, '#2A1840');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // Cakram latar di belakang cincin
  ctx.fillStyle = '#141846';
  ctx.beginPath();
  ctx.arc(S.cx, S.cy, S.u * 0.445, 0, TAU);
  ctx.fill();

  // Garis hairline batas ruang teks
  ctx.strokeStyle = 'rgba(242,193,78,0.6)';
  ctx.lineWidth = S.u * 0.0025;
  ctx.beginPath();
  ctx.arc(S.cx, S.cy, S.u * 0.262, 0, TAU);
  ctx.stroke();
}

function drawStars(ctx, S, p) {
  for (let i = 0; i < S.stars.length; i++) {
    const s = S.stars[i];
    const tw = 0.5 + 0.5 * Math.sin(TAU * s.k * p + s.ph);
    ctx.globalAlpha = 0.4 + 0.6 * tw;
    if (s.sparkle) {
      ctx.fillStyle = '#FFF1CF';
      drawSparkle(ctx, s.x, s.y, s.r * (0.84 + 0.16 * tw));
    } else {
      ctx.fillStyle = '#D6D0FF';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, TAU);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
}

function drawDashRings(ctx, S, E) {
  const u = S.u;
  ctx.strokeStyle = 'rgba(255,241,207,0.2)';
  ctx.lineWidth = u * 0.0022;
  ctx.lineCap = 'butt';
  for (let i = 0; i < S.dashRings.length; i++) {
    const d = S.dashRings[i];
    const period = (TAU * d.r) / d.N;
    ctx.setLineDash([period * 0.5, period * 0.5]);
    ctx.lineDashOffset = -d.dir * d.m * period * E;
    ctx.beginPath();
    ctx.arc(S.cx, S.cy, d.r, 0, TAU);
    ctx.stroke();
  }
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
}

function drawGapDots(ctx, S, E) {
  const u = S.u;
  for (let g = 0; g < S.gaps.length; g++) {
    const G = S.gaps[g];
    const shift = G.dir * G.m * ((2 * TAU) / G.N) * E;
    for (let q = 0; q < 2; q++) {
      ctx.fillStyle = q === 0 ? '#FFE7A3' : '#E8A6A0';
      ctx.beginPath();
      for (let i = q; i < G.N; i += 2) {
        const a = (i * TAU) / G.N + shift;
        const x = S.cx + Math.cos(a) * G.r;
        const y = S.cy + Math.sin(a) * G.r;
        const rr = q === 0 ? u * 0.0042 : u * 0.0026;
        ctx.moveTo(x + rr, y);
        ctx.arc(x, y, rr, 0, TAU);
      }
      ctx.fill();
    }
  }
}

function drawRibbon(ctx, S, R, E) {
  const cx = S.cx;
  const cy = S.cy;
  const psi = R.dir * TAU * R.m * E;
  const n = R.n;
  const K = 10;

  // Alas tipis agar tidak ada garis celah di titik putar pita
  ctx.strokeStyle = R.B;
  ctx.lineWidth = R.H * 0.4;
  ctx.beginPath();
  ctx.arc(cx, cy, R.r, 0, TAU);
  ctx.stroke();

  for (let pass = 0; pass < 2; pass++) {
    ctx.fillStyle = pass === 0 ? R.B : R.A;
    ctx.beginPath();
    for (let m = pass; m < 2 * n; m += 2) {
      const f0 = (Math.PI / 2 + m * Math.PI - psi) / n;
      const f1 = f0 + Math.PI / n;
      for (let s = 0; s <= K; s++) {
        const f = f0 + ((f1 - f0) * s) / K;
        const w = R.H * (0.2 + 0.8 * Math.abs(Math.cos(n * f + psi)));
        const x = cx + Math.cos(f) * (R.r + w);
        const y = cy + Math.sin(f) * (R.r + w);
        if (s === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      for (let s = K; s >= 0; s--) {
        const f = f0 + ((f1 - f0) * s) / K;
        const w = R.H * (0.2 + 0.8 * Math.abs(Math.cos(n * f + psi)));
        ctx.lineTo(cx + Math.cos(f) * (R.r - w), cy + Math.sin(f) * (R.r - w));
      }
      ctx.closePath();
    }
    ctx.fill();
  }
}

function drawOrbitSparkles(ctx, S, p, E) {
  const u = S.u;
  const step = TAU / S.orbitN;
  const shift = -2 * step * E;
  for (let i = 0; i < S.orbitN; i++) {
    const a = i * step + shift;
    // Gelombang denyut berjalan mengelilingi lingkaran (3 puncak, 2 putaran per loop)
    const f = 0.5 + 0.5 * Math.cos(3 * a - TAU * 2 * p);
    const x = S.cx + Math.cos(a) * S.orbitR;
    const y = S.cy + Math.sin(a) * S.orbitR;
    ctx.globalAlpha = 0.55 + 0.45 * f;
    ctx.fillStyle = i % 2 === 0 ? '#FFF1CF' : '#F7D774';
    drawSparkle(ctx, x, y, u * (0.0075 + 0.0055 * f));
  }
  ctx.globalAlpha = 1;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;
  const E = ease(p);

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawBackground(ctx, S, width, height);
  drawStars(ctx, S, p);
  drawDashRings(ctx, S, E);
  drawGapDots(ctx, S, E);
  for (let i = 0; i < S.rings.length; i++) drawRibbon(ctx, S, S.rings[i], E);
  drawOrbitSparkles(ctx, S, p, E);

  ctx.restore();
}

// KONSEP 5 — CONFETTI BURST PARTY BACKGROUND
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildScene(width, height) {
  const u = Math.min(width, height);
  const rnd = rng(20270105);

  // Confetti: jalur (lane) vertikal di sisi kiri/kanan, tengah dibiarkan bersih untuk copy space.
  // Jarak antarjalur (0.04u) selalu lebih besar dari ukuran maksimum dua confetti bertetangga + ayunan.
  const laneN = [24, 22, 20, 16, 12];
  const palette = ['#FFD23F', '#FFFFFF', '#FF7A59', '#2B2D6E', '#C9B6FF', '#FFE8A3'];
  const span = height + u * 0.08;
  const pieces = [];

  for (let side = 0; side < 2; side++) {
    for (let li = 0; li < 5; li++) {
      const off = rnd();
      const near = li % 2 === 0;
      const n = laneN[li];
      const laneOff = u * (0.21 + 0.04 * li);
      const baseX = side === 0 ? laneOff : width - laneOff;
      for (let j = 0; j < n; j++) {
        const sc = (near ? 1.0 : 0.55) * (0.85 + rnd() * 0.15);
        const type = Math.floor(rnd() * 4);
        pieces.push({
          x: baseX + (rnd() - 0.5) * u * 0.006,
          phase: (j + off + (rnd() - 0.5) * 0.3) / n,
          cyc: near ? (li === 2 ? 3 : 2) : 1,
          type: type,
          sc: sc,
          col: palette[Math.floor(rnd() * palette.length)],
          rot: rnd() * TAU,
          rc: 1 + Math.floor(rnd() * 2),
          dir: rnd() < 0.5 ? 1 : -1,
          fc: 2 + Math.floor(rnd() * 2),
          fph: rnd() * TAU,
          sk: 1 + Math.floor(rnd() * 2),
          sph: rnd() * TAU,
          amp: u * (near ? 0.005 : 0.003)
        });
      }
    }
  }

  // Serpentine (pita heliks berpilin proporsional) di tepi kiri; sisi kanan adalah cerminannya
  const streamers = [
    {
      xc: 0.055 * u,
      amp: 0.022 * u,
      lam: 0.26 * u,
      swayAmp: 0.0035 * u,
      swayLam: 0.65 * u,
      dirW: 1,
      cyc: 2,
      phW: 0.0,
      H: 0.035 * u,
      A: '#FFD23F',
      B: '#D9A400'
    },
    {
      xc: 0.135 * u,
      amp: 0.020 * u,
      lam: 0.23 * u,
      swayAmp: 0.003 * u,
      swayLam: 0.55 * u,
      dirW: -1,
      cyc: 2,
      phW: 1.8,
      H: 0.031 * u,
      A: '#FF7A59',
      B: '#C94A3A'
    }
  ];

  return {
    key: width + 'x' + height,
    u: u,
    span: span,
    pieces: pieces,
    streamers: streamers
  };
}

function drawBackground(ctx, S, p, width, height) {
  const u = S.u;
  const g = ctx.createLinearGradient(0, 0, width, height);
  g.addColorStop(0, '#0AB5A8');
  g.addColorStop(0.5, '#4A5BD8');
  g.addColorStop(1, '#C2187A');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // Cincin tipis di area tengah (tidak menyentuh jalur confetti)
  const cx = width / 2;
  const cy = height / 2;
  ctx.strokeStyle = 'rgba(255,255,255,0.14)';
  ctx.lineWidth = u * 0.0025;
  ctx.beginPath();
  ctx.arc(cx, cy, u * 0.3, 0, TAU);
  ctx.stroke();

  const r2 = u * 0.42;
  const period = (TAU * r2) / 120;
  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
  ctx.setLineDash([period * 0.5, period * 0.5]);
  ctx.lineDashOffset = -4 * period * p;
  ctx.beginPath();
  ctx.arc(cx, cy, r2, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
}

function drawStreamer(ctx, S, st, p, mirror, width, height) {
  const u = S.u;
  const b = st.H;
  const y0 = -u * 0.08;
  const y1 = height + u * 0.08;
  const mx = function (x) {
    return mirror ? width - x : x;
  };

  const cyc = st.cyc || 1;
  const s = st.dirW * cyc * TAU * p;
  const swayPhase = st.phW - st.dirW * TAU * p;
  const phi = st.phW - s;

  const axisX = function (y) {
    return st.xc + st.swayAmp * Math.sin((TAU * y) / st.swayLam + swayPhase);
  };
  const yAt = function (th, dy) {
    return ((th - phi) * st.lam) / TAU + dy;
  };
  const xAt = function (th, y) {
    return mx(axisX(y) + st.amp * Math.sin(th));
  };

  const mOf = function (y) {
    return ((TAU * y) / st.lam + phi) / Math.PI;
  };
  const mStart = Math.floor(mOf(y0)) - 2;
  const mEnd = Math.ceil(mOf(y1)) + 2;
  const steps = 24;
  const inset = 0.12;

  // Pass 0 = segmen pita bagian belakang (st.B), Pass 1 = segmen pita bagian depan (st.A)
  for (let pass = 0; pass < 2; pass++) {
    ctx.fillStyle = pass === 0 ? st.B : st.A;
    ctx.beginPath();

    for (let m = mStart; m <= mEnd; m++) {
      if ((((m % 2) + 2) % 2) !== pass) continue;

      const thA = m * Math.PI - Math.PI / 2;
      const thB = m * Math.PI + Math.PI / 2;

      const topStart = pass === 0 ? thA + inset : thA;
      const topEnd = thB;
      const botStart = thA;
      const botEnd = pass === 0 ? thB - inset : thB;

      // Kurva tepi atas pita
      for (let i = 0; i <= steps; i++) {
        const th = topStart + ((topEnd - topStart) * i) / steps;
        const y = yAt(th, -b);
        const x = xAt(th, y);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }

      // Lipatan vertikal di ujung akhir segmen depan
      if (pass === 1) {
        for (let j = 1; j <= 4; j++) {
          const dy = -b + (2 * b * j) / 4;
          const y = yAt(thB, dy);
          ctx.lineTo(xAt(thB, y), y);
        }
      }

      // Kurva tepi bawah pita
      for (let i = steps; i >= 0; i--) {
        const th = botStart + ((botEnd - botStart) * i) / steps;
        const y = yAt(th, b);
        const x = xAt(th, y);
        ctx.lineTo(x, y);
      }

      // Lipatan vertikal di ujung awal segmen depan
      if (pass === 1) {
        for (let j = 1; j < 4; j++) {
          const dy = b - (2 * b * j) / 4;
          const y = yAt(thA, dy);
          ctx.lineTo(xAt(thA, y), y);
        }
      }

      ctx.closePath();
    }

    ctx.fill();
  }
}

function drawConfetti(ctx, S, p, height) {
  const u = S.u;
  const yStart = -u * 0.04;
  for (let i = 0; i < S.pieces.length; i++) {
    const c = S.pieces[i];
    const prog = (((c.phase + c.cyc * p) % 1) + 1) % 1;
    const y = yStart + prog * S.span;
    const x = c.x + Math.sin(TAU * c.sk * p + c.sph) * c.amp;
    const rot = c.rot + TAU * c.rc * c.dir * p;
    const flip = 0.7 + 0.3 * Math.cos(TAU * c.fc * p + c.fph);

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.scale(1, flip);
    ctx.fillStyle = c.col;
    const sc = c.sc;
    if (c.type === 0) {
      const s = u * 0.016 * sc;
      ctx.fillRect(-s / 2, -s / 2, s, s);
    } else if (c.type === 1) {
      const w = u * 0.006 * sc;
      const h = u * 0.026 * sc;
      ctx.fillRect(-w / 2, -h / 2, w, h);
    } else if (c.type === 2) {
      ctx.beginPath();
      ctx.arc(0, 0, u * 0.009 * sc, 0, TAU);
      ctx.fill();
    } else {
      const r = u * 0.0115 * sc;
      ctx.beginPath();
      ctx.moveTo(0, -r);
      ctx.lineTo(r * 0.866, r * 0.5);
      ctx.lineTo(-r * 0.866, r * 0.5);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawBackground(ctx, S, p, width, height);
  for (let i = 0; i < S.streamers.length; i++) {
    drawStreamer(ctx, S, S.streamers[i], p, false, width, height);
    drawStreamer(ctx, S, S.streamers[i], p, true, width, height);
  }
  drawConfetti(ctx, S, p, height);

  ctx.restore();
}

// KONSEP 6 — GIFT BOXES & PARTY HATS FLOATING
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function smooth(v) {
  v = v < 0 ? 0 : v > 1 ? 1 : v;
  return v * v * (3 - 2 * v);
}

// Tipe: 0 hadiah, 1 topi pesta, 2 balon, 3 terompet
// Radius pembatas (satuan b) untuk menjaga jarak antarobjek
const RAD = [9.3, 11.0, 14.7, 9.0];

const GIFT_V = [
  { body: '#FF6B6B', lid: '#E04F5F', rib: '#F2C14E', ribD: '#D9A400' },
  { body: '#22C1B5', lid: '#159A91', rib: '#FFF1CF', ribD: '#E2CFA0' },
  { body: '#8F7CF0', lid: '#6F5BD6', rib: '#F2C14E', ribD: '#D9A400' }
];
const HAT_V = [
  { cone: '#F2C14E', stripe: '#FF6B6B', band: '#FFF1CF', pom: '#FF6B6B' },
  { cone: '#22C1B5', stripe: '#FFF1CF', band: '#F2C14E', pom: '#F2C14E' },
  { cone: '#8F7CF0', stripe: '#F2C14E', band: '#FFF1CF', pom: '#FFF1CF' }
];
const BAL_V = ['#FF6B6B', '#F2C14E', '#22C1B5', '#9D8BFF'];
const HORN_V = [
  { body: '#22C1B5', stripe: '#FFF1CF', rim: '#159A91', mouth: '#F2C14E' },
  { body: '#FF6B6B', stripe: '#F2C14E', rim: '#D94B58', mouth: '#FFF1CF' },
  { body: '#F2C14E', stripe: '#FF6B6B', rim: '#D9A400', mouth: '#FF6B6B' }
];

function buildScene(width, height) {
  const u = Math.min(width, height);
  const b = u * 0.0065;
  const rnd = rng(20270106);

  // Urutan tipe per jalur (tidak ada dua balon bersebelahan, termasuk saat wrap)
  const seqs = [
    [[2, 0, 1, 3, 2, 3], [0, 2, 3, 1, 2, 1]],
    [[1, 2, 0, 3, 2, 0], [3, 2, 1, 0, 2, 0]]
  ];
  const laneX0 = [0.12 * u, 0.32 * u];
  const laneSc = [0.8, 1.0];
  const mTop = 0.12 * u;
  const mBot = 0.12 * u;
  const span = height + mTop + mBot;
  const n = 6;

  const objs = [];
  for (let side = 0; side < 2; side++) {
    for (let li = 0; li < 2; li++) {
      // Jalur dalam digeser setengah jarak vertikal terhadap jalur luar
      const off = (side === 0 ? 0.1 : 0.35) / n + (li === 1 ? 0.5 / n : 0);
      for (let j = 0; j < n; j++) {
        const type = seqs[side][li][j];
        const v = (li * 3 + j) % (type === 2 ? 4 : 3);
        objs.push({
          type: type,
          v: v,
          side: side,
          sc: laneSc[li],
          x0: laneX0[li],
          phase: (j + off * n) / n,
          rad: RAD[type] * b * laneSc[li],
          tiltBase: type === 1 ? (rnd() - 0.5) * 0.2 : type === 0 ? (rnd() - 0.5) * 0.1 : 0,
          tiltAmp: 0.1,
          tk: 1 + Math.floor(rnd() * 2),
          tph: rnd() * TAU,
          sk: 1 + Math.floor(rnd() * 2),
          sph: rnd() * TAU,
          ampX: u * 0.006
        });
      }
    }
  }

  // Bintang kecil di strip atas/bawah tengah
  const stars = [];
  let tries = 0;
  while (stars.length < 14 && tries < 4000) {
    tries++;
    const x = width / 2 + (rnd() - 0.5) * (width - 1.2 * u);
    const top = rnd() < 0.5;
    const y = top ? u * (0.04 + rnd() * 0.08) : height - u * (0.04 + rnd() * 0.08);
    let ok = true;
    for (let s = 0; s < stars.length; s++) {
      if (Math.hypot(x - stars[s].x, y - stars[s].y) < u * 0.08) { ok = false; break; }
    }
    if (!ok) continue;
    const sparkle = stars.length % 2 === 0;
    stars.push({
      x: x, y: y, sparkle: sparkle,
      r: sparkle ? u * (0.009 + rnd() * 0.006) : u * 0.003,
      ph: rnd() * TAU, k: 1 + Math.floor(rnd() * 2)
    });
  }

  return {
    key: width + 'x' + height,
    u: u, b: b, span: span, mBot: mBot, objs: objs, stars: stars
  };
}

function drawSparkle(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.3;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
}

function rect(ctx, b, x0, y0, x1, y1) {
  ctx.fillRect(x0 * b, y0 * b, (x1 - x0) * b, (y1 - y0) * b);
}

function drawGift(ctx, b, c) {
  ctx.translate(0, 1.55 * b);
  ctx.fillStyle = c.body;
  rect(ctx, b, -5, -2.4, 5, 5.6);
  ctx.fillStyle = c.lid;
  rect(ctx, b, -5.8, -5.1, 5.8, -2.4);
  ctx.fillStyle = c.rib;
  rect(ctx, b, -1, -5.1, 1, 5.6);
  rect(ctx, b, -5, 1.4, 5, 2.6);
  // Pita (bow)
  ctx.fillStyle = c.ribD;
  for (let s = -1; s <= 1; s += 2) {
    ctx.save();
    ctx.translate(s * 2.4 * b, -6.9 * b);
    ctx.rotate(s * -0.45);
    ctx.beginPath();
    ctx.ellipse(0, 0, 2.4 * b, 1.4 * b, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
  ctx.fillStyle = c.rib;
  ctx.beginPath();
  ctx.arc(0, -6.2 * b, 1.0 * b, 0, TAU);
  ctx.fill();
}

function drawHat(ctx, b, c) {
  ctx.translate(0, 2.55 * b);
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(0, -10 * b);
  ctx.lineTo(5.5 * b, 7 * b);
  ctx.lineTo(-5.5 * b, 7 * b);
  ctx.closePath();
  ctx.fillStyle = c.cone;
  ctx.fill();
  ctx.clip();
  ctx.fillStyle = c.stripe;
  const ys = [-5, -1.5, 2];
  for (let k = 0; k < ys.length; k++) {
    ctx.beginPath();
    ctx.moveTo(-8 * b, ys[k] * b);
    ctx.lineTo(8 * b, (ys[k] - 3) * b);
    ctx.lineTo(8 * b, (ys[k] - 1.6) * b);
    ctx.lineTo(-8 * b, (ys[k] + 1.4) * b);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
  ctx.fillStyle = c.band;
  ctx.beginPath();
  ctx.moveTo(-5.05 * b, 5.6 * b);
  ctx.lineTo(5.05 * b, 5.6 * b);
  ctx.lineTo(5.5 * b, 7 * b);
  ctx.lineTo(-5.5 * b, 7 * b);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = c.pom;
  ctx.beginPath();
  ctx.arc(0, -10.6 * b, 1.5 * b, 0, TAU);
  ctx.fill();
}

function drawBalloon(ctx, b, color) {
  ctx.translate(0, 0.3 * b);
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.ellipse(0, -6 * b, 6.2 * b, 7.6 * b, 0, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(0, 1.5 * b);
  ctx.lineTo(-1.1 * b, 3.0 * b);
  ctx.lineTo(1.1 * b, 3.0 * b);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,241,207,0.45)';
  ctx.save();
  ctx.translate(-2.4 * b, -9 * b);
  ctx.rotate(-0.4);
  ctx.beginPath();
  ctx.ellipse(0, 0, 1.2 * b, 2.2 * b, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
  ctx.strokeStyle = 'rgba(255,241,207,0.85)';
  ctx.lineWidth = 0.3 * b;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(0, 3.0 * b);
  ctx.bezierCurveTo(-2.5 * b, 5.5 * b, 2.5 * b, 9 * b, 0, 13 * b);
  ctx.stroke();
}

function drawHorn(ctx, b, c) {
  ctx.rotate(-0.7);
  ctx.translate(1.5 * b, 0);
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(-8 * b, -1.3 * b);
  ctx.lineTo(6 * b, -4.6 * b);
  ctx.lineTo(6 * b, 4.6 * b);
  ctx.lineTo(-8 * b, 1.3 * b);
  ctx.closePath();
  ctx.fillStyle = c.body;
  ctx.fill();
  ctx.clip();
  ctx.fillStyle = c.stripe;
  rect(ctx, b, -4.6, -6, -3.2, 6);
  rect(ctx, b, -0.6, -6, 0.8, 6);
  rect(ctx, b, 3.4, -6, 4.8, 6);
  ctx.restore();
  ctx.fillStyle = c.rim;
  ctx.beginPath();
  ctx.ellipse(6 * b, 0, 1.2 * b, 4.6 * b, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = c.mouth;
  ctx.beginPath();
  ctx.arc(-8.8 * b, 0, 1.4 * b, 0, TAU);
  ctx.fill();
}

function drawBackground(ctx, S, p, width, height) {
  const u = S.u;
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#0B1239');
  g.addColorStop(1, '#1E2B73');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // Cincin tipis di tengah (di dalam area kosong)
  const cx = width / 2;
  const cy = height / 2;
  ctx.strokeStyle = 'rgba(255,241,207,0.14)';
  ctx.lineWidth = u * 0.0025;
  ctx.beginPath();
  ctx.arc(cx, cy, u * 0.3, 0, TAU);
  ctx.stroke();

  const r2 = u * 0.4;
  const period = (TAU * r2) / 120;
  ctx.strokeStyle = 'rgba(255,241,207,0.2)';
  ctx.setLineDash([period * 0.5, period * 0.5]);
  ctx.lineDashOffset = -3 * period * p;
  ctx.beginPath();
  ctx.arc(cx, cy, r2, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
}

function drawStars(ctx, S, p) {
  for (let i = 0; i < S.stars.length; i++) {
    const s = S.stars[i];
    const tw = 0.5 + 0.5 * Math.sin(TAU * s.k * p + s.ph);
    ctx.globalAlpha = 0.4 + 0.6 * tw;
    if (s.sparkle) {
      ctx.fillStyle = '#FFF1CF';
      drawSparkle(ctx, s.x, s.y, s.r * (0.84 + 0.16 * tw));
    } else {
      ctx.fillStyle = '#D6D0FF';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, TAU);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
}

// Posisi objek (dipakai untuk menggambar); jalur sedikit melengkung mengikuti bingkai oval
function objPos(S, o, p, width, height) {
  const u = S.u;
  const prog = (((o.phase + p) % 1) + 1) % 1;
  const y = height + S.mBot - prog * S.span;
  const q = (y - height / 2) / (height / 2);
  const xl = o.x0 + u * 0.05 * q * q + Math.sin(TAU * o.sk * p + o.sph) * o.ampX;
  const x = o.side === 0 ? xl : width - xl;
  return { x: x, y: y };
}

function drawObjects(ctx, S, p, width, height) {
  const b = S.b;
  for (let i = 0; i < S.objs.length; i++) {
    const o = S.objs[i];
    const pos = objPos(S, o, p, width, height);
    const tilt = o.tiltBase + o.tiltAmp * Math.sin(TAU * o.tk * p + o.tph);

    ctx.save();
    ctx.translate(pos.x, pos.y);
    if (o.side === 1) ctx.scale(-1, 1);
    ctx.scale(o.sc, o.sc);
    ctx.rotate(tilt);
    if (o.type === 0) drawGift(ctx, b, GIFT_V[o.v]);
    else if (o.type === 1) drawHat(ctx, b, HAT_V[o.v]);
    else if (o.type === 2) drawBalloon(ctx, b, BAL_V[o.v]);
    else drawHorn(ctx, b, HORN_V[o.v]);
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawBackground(ctx, S, p, width, height);
  drawStars(ctx, S, p);
  drawObjects(ctx, S, p, width, height);

  ctx.restore();
}

// KONSEP 7 — SNOWY WINTER NIGHT COUNTDOWN HILL
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function smooth(v) {
  v = v < 0 ? 0 : v > 1 ? 1 : v;
  return v * v * (3 - 2 * v);
}

// Tingkatan pohon pinus (relatif terhadap tinggi h; y negatif = ke atas dari dasar)
const TIERS = [
  { a: -0.52, b: -0.10, hw: 0.26 },
  { a: -0.76, b: -0.36, hw: 0.21 },
  { a: -1.0, b: -0.58, hw: 0.15 }
];

const CRATERS = [
  [-0.38, 0.12, 0.17], [0.28, -0.28, 0.11], [0.22, 0.38, 0.14],
  [-0.12, -0.5, 0.07], [0.58, 0.05, 0.08], [-0.55, -0.25, 0.06]
];

function buildScene(width, height) {
  const u = Math.min(width, height);
  const rnd = rng(20270107);

  const hills = [
    { base: 0.64, a1: 0.035, l1: 2.4, p1: 4.0, a2: 0.015, l2: 1.0, p2: 1.0, col: '#3F4D9E', shade: '#35428C' },
    { base: 0.77, a1: 0.03, l1: 1.9, p1: 2.0, a2: 0.015, l2: 0.8, p2: 0.3, col: '#6F80C9', shade: '#5F70B9' },
    { base: 0.87, a1: 0.022, l1: 1.6, p1: 0.5, a2: 0.013, l2: 0.7, p2: 1.2, col: '#E8EEFF', shade: '#C9D6F4' }
  ];
  const hillY = function (L, x) {
    const h = hills[L];
    return u * h.base + u * h.a1 * Math.sin((TAU * x) / (u * h.l1) + h.p1) + u * h.a2 * Math.sin((TAU * x) / (u * h.l2) + h.p2);
  };

  const makeTree = function (L, x, h) {
    const base = hillY(L, x) + 0.01 * h;
    return { L: L, x: x, base: base, h: h, x0: x - 0.26 * h, x1: x + 0.26 * h, y0: base - h, y1: base + 0.02 * h };
  };

  // Pohon depan (tetap), dua di antaranya menjadi tiang lampu string
  const near = [
    makeTree(2, width * 0.09, u * 0.30),
    makeTree(2, width * 0.35, u * 0.34),
    makeTree(2, width * 0.686, u * 0.34),
    makeTree(2, width * 0.911, u * 0.30)
  ];

  // Lampu string: dari ujung tingkat 2 pohon kiri ke ujung tingkat 2 pohon kanan
  const tl = near[1];
  const tr = near[2];
  const Ax = tl.x + TIERS[1].hw * tl.h;
  const Ay = tl.base + TIERS[1].b * tl.h;
  const Bx = tr.x - TIERS[1].hw * tr.h;
  const By = tr.base + TIERS[1].b * tr.h;
  const light = { Ax: Ax, Ay: Ay, Bx: Bx, By: By, sag: u * 0.05, N: 16 };
  const lightBox = {
    x0: Ax, x1: Bx,
    y0: Math.min(Ay, By) - u * 0.015,
    y1: Math.max(Ay, By) + light.sag + u * 0.03
  };

  const overlaps = function (a, b, m) {
    return a.x0 < b.x1 + m && a.x1 > b.x0 - m && a.y0 < b.y1 + m && a.y1 > b.y0 - m;
  };
  const placed = near.slice();
  const mid = [];
  const far = [];
  const margin = u * 0.012;

  for (let x = u * 0.05; x < width - u * 0.05; x += u * 0.012) {
    if (rnd() < 0.5) continue;
    const t = makeTree(1, x, u * (0.15 + 0.04 * rnd()));
    let ok = !overlaps(t, lightBox, margin);
    for (let i = 0; ok && i < placed.length; i++) if (overlaps(t, placed[i], margin)) ok = false;
    if (!ok) continue;
    placed.push(t);
    mid.push(t);
    x += t.h * 0.3;
  }
  for (let x = u * 0.05; x < width - u * 0.05; x += u * 0.012) {
    if (rnd() < 0.5) continue;
    const t = makeTree(0, x, u * (0.08 + 0.03 * rnd()));
    let ok = !overlaps(t, lightBox, margin);
    for (let i = 0; ok && i < placed.length; i++) if (overlaps(t, placed[i], margin)) ok = false;
    if (!ok) continue;
    placed.push(t);
    far.push(t);
    x += t.h * 0.3;
  }
  const allTrees = near.concat(mid, far);

  // Bulan
  const moon = { x: width * 0.8, y: u * 0.26, r: u * 0.15 };

  // Tinggi permukaan terdekat (bukit, pohon, lampu) di posisi x — dipakai agar salju memudar sebelum menyentuhnya
  const treeTop = function (t, x) {
    const dx = Math.abs(x - t.x);
    let best = Infinity;
    for (let i = 0; i < TIERS.length; i++) {
      const T = TIERS[i];
      const hw = T.hw * t.h;
      if (dx <= hw) {
        const y = t.base + T.a * t.h + (dx * (T.b - T.a) * t.h) / hw;
        if (y < best) best = y;
      }
    }
    return best;
  };
  const wireY = function (x) {
    const tt = (x - light.Ax) / (light.Bx - light.Ax);
    return light.Ay + (light.By - light.Ay) * tt + 4 * light.sag * tt * (1 - tt);
  };
  const ground = function (x) {
    let g = Infinity;
    for (let L = 0; L < 3; L++) g = Math.min(g, hillY(L, x));
    for (let i = 0; i < allTrees.length; i++) g = Math.min(g, treeTop(allTrees[i], x));
    if (x >= light.Ax && x <= light.Bx) g = Math.min(g, wireY(x) - u * 0.012);
    return g;
  };

  // Jalur salju (lane) — dua lapis, jarak antarjalur 0.06u
  const lanes = [];
  const nLanes = Math.floor((width - u * 0.06) / (u * 0.06)) + 1;
  const span = height + u * 0.06;
  for (let k = 0; k < nLanes; k++) {
    const x = u * 0.03 + k * u * 0.06;
    const nearLayer = k % 2 === 0;
    const r = u * (nearLayer ? 0.0055 : 0.0033);
    const pad = r + u * 0.006;
    let gmin = Infinity;
    for (let dx = -0.0125; dx <= 0.0125001; dx += 0.0025) gmin = Math.min(gmin, ground(x + dx * u));
    const lim = gmin - pad;
    const inMoon = Math.abs(x - moon.x) < moon.r + u * 0.03;
    const off = rnd();
    const n = 8;
    for (let j = 0; j < n; j++) {
      lanes.push({
        x: x, r: r, lim: lim,
        yMin: inMoon ? moon.y + moon.r + u * 0.03 : -Infinity,
        phase: (j + off) / n,
        cyc: nearLayer ? 2 : 1,
        amp: u * (nearLayer ? 0.006 : 0.004),
        sk: 1 + ((j + k) % 2),
        sph: rnd() * TAU,
        a: nearLayer ? 0.95 : 0.65
      });
    }
  }

  // Bintang: di tengah antar-jalur salju (tidak pernah dilewati kepingan salju)
  const stars = [];
  let tries = 0;
  while (stars.length < 40 && tries < 8000) {
    tries++;
    const k = Math.floor(rnd() * (nLanes - 1));
    const x = u * 0.03 + k * u * 0.06 + u * 0.03;
    const y = u * 0.04 + rnd() * u * 0.42;
    if (Math.hypot(x - moon.x, y - moon.y) < moon.r + u * 0.06) continue;
    let ok = true;
    for (let s = 0; s < stars.length; s++) {
      if (Math.hypot(x - stars[s].x, y - stars[s].y) < u * 0.07) { ok = false; break; }
    }
    if (!ok) continue;
    const sparkle = stars.length % 3 === 0;
    stars.push({
      x: x, y: y, sparkle: sparkle,
      r: sparkle ? u * (0.008 + rnd() * 0.004) : u * (0.002 + rnd() * 0.0015),
      ph: rnd() * TAU, k: 1 + Math.floor(rnd() * 2)
    });
  }

  return {
    key: width + 'x' + height,
    u: u, hills: hills, hillY: hillY,
    near: near, mid: mid, far: far, light: light, wireY: wireY,
    moon: moon, lanes: lanes, stars: stars, span: span, ground: ground
  };
}

function drawSparkle(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.3;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
}

function drawSky(ctx, width, height) {
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#050B26');
  g.addColorStop(0.55, '#14235E');
  g.addColorStop(1, '#3A4A9A');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawStars(ctx, S, p) {
  for (let i = 0; i < S.stars.length; i++) {
    const s = S.stars[i];
    const tw = 0.5 + 0.5 * Math.sin(TAU * s.k * p + s.ph);
    ctx.globalAlpha = 0.4 + 0.6 * tw;
    if (s.sparkle) {
      ctx.fillStyle = '#FFF1CF';
      drawSparkle(ctx, s.x, s.y, s.r * (0.84 + 0.16 * tw));
    } else {
      ctx.fillStyle = '#D6D0FF';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, TAU);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
}

function drawMoon(ctx, S, p) {
  const u = S.u;
  const m = S.moon;
  const cy = m.y + u * 0.004 * Math.sin(TAU * p);
  ctx.save();
  ctx.beginPath();
  ctx.arc(m.x, cy, m.r, 0, TAU);
  ctx.fillStyle = '#D9D2BA';
  ctx.fill();
  ctx.clip();
  ctx.fillStyle = '#F4EEDC';
  ctx.beginPath();
  ctx.arc(m.x - m.r * 0.04, cy - m.r * 0.04, m.r * 0.94, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#CFC7AB';
  for (let i = 0; i < CRATERS.length; i++) {
    const c = CRATERS[i];
    ctx.beginPath();
    ctx.arc(m.x + c[0] * m.r, cy + c[1] * m.r, c[2] * m.r, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawHill(ctx, S, L, width, height) {
  const u = S.u;
  const h = S.hills[L];
  const step = u * 0.01;
  const x0 = -u * 0.02;
  const x1 = width + u * 0.02;
  ctx.fillStyle = h.col;
  ctx.beginPath();
  for (let x = x0; x <= x1 + 0.5; x += step) {
    const y = S.hillY(L, x);
    if (x === x0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.lineTo(x1, height + u * 0.02);
  ctx.lineTo(x0, height + u * 0.02);
  ctx.closePath();
  ctx.fill();

  // Bayangan datar bagian bawah bukit
  ctx.fillStyle = h.shade;
  ctx.beginPath();
  for (let x = x0; x <= x1 + 0.5; x += step) {
    const y = S.hillY(L, x) + u * 0.03;
    if (x === x0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.lineTo(x1, height + u * 0.02);
  ctx.lineTo(x0, height + u * 0.02);
  ctx.closePath();
  ctx.fill();
}

function drawPine(ctx, t, col, snow, trunk) {
  const h = t.h;
  ctx.fillStyle = trunk;
  ctx.fillRect(t.x - 0.035 * h, t.base - 0.13 * h, 0.07 * h, 0.15 * h);
  for (let i = 0; i < TIERS.length; i++) {
    const T = TIERS[i];
    const hw = T.hw * h;
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(t.x, t.base + T.a * h);
    ctx.lineTo(t.x + hw, t.base + T.b * h);
    ctx.lineTo(t.x - hw, t.base + T.b * h);
    ctx.closePath();
    ctx.fill();
    if (snow) {
      const yd = t.base + T.a * h + 0.45 * (T.b - T.a) * h;
      const hwd = hw * 0.45;
      ctx.fillStyle = snow;
      ctx.beginPath();
      ctx.moveTo(t.x, t.base + T.a * h);
      ctx.lineTo(t.x + hwd, yd);
      ctx.lineTo(t.x + hwd * 0.5, yd - 0.035 * h);
      ctx.lineTo(t.x, yd);
      ctx.lineTo(t.x - hwd * 0.5, yd - 0.035 * h);
      ctx.lineTo(t.x - hwd, yd);
      ctx.closePath();
      ctx.fill();
    }
  }
}

function drawTrees(ctx, list, col, snow, trunk) {
  for (let i = 0; i < list.length; i++) drawPine(ctx, list[i], col, snow, trunk);
}

function drawLights(ctx, S, p) {
  const u = S.u;
  const L = S.light;
  const colors = ['#FFC83D', '#FF6B6B', '#22C1B5', '#FFF1CF'];

  // Kabel
  ctx.strokeStyle = '#0E1A44';
  ctx.lineWidth = u * 0.0025;
  ctx.lineCap = 'round';
  ctx.beginPath();
  for (let i = 0; i <= 40; i++) {
    const t = i / 40;
    const x = L.Ax + (L.Bx - L.Ax) * t;
    const y = L.Ay + (L.By - L.Ay) * t + 4 * L.sag * t * (1 - t);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.stroke();

  // Bohlam: dasar gelap + lapisan warna dengan kecerahan berombak (tanpa halo)
  for (let i = 0; i < L.N; i++) {
    const t = (i + 0.5) / L.N;
    const x = L.Ax + (L.Bx - L.Ax) * t;
    const yw = L.Ay + (L.By - L.Ay) * t + 4 * L.sag * t * (1 - t);
    ctx.fillStyle = '#0E1A44';
    ctx.fillRect(x - u * 0.0025, yw + u * 0.001, u * 0.005, u * 0.006);
    const cy = yw + u * 0.0135;
    ctx.fillStyle = '#2B3270';
    ctx.beginPath();
    ctx.arc(x, cy, u * 0.0068, 0, TAU);
    ctx.fill();
    const a = 0.25 + 0.75 * (0.5 + 0.5 * Math.cos(TAU * (3 * p - (i % 4) / 4)));
    ctx.globalAlpha = a;
    ctx.fillStyle = colors[i % 4];
    ctx.beginPath();
    ctx.arc(x, cy, u * 0.0068, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = 1;
  }
}

function drawSnow(ctx, S, p) {
  const u = S.u;
  const fade = u * 0.05;
  const yStart = -u * 0.04;
  ctx.fillStyle = '#FFFFFF';
  for (let i = 0; i < S.lanes.length; i++) {
    const f = S.lanes[i];
    const prog = (((f.phase + f.cyc * p) % 1) + 1) % 1;
    const y = yStart + prog * S.span;
    let a = smooth((f.lim - y) / fade);
    if (f.yMin > -1e8) a *= smooth((y - f.yMin) / fade);
    a *= f.a;
    if (a < 0.01) continue;
    const x = f.x + Math.sin(TAU * f.sk * p + f.sph) * f.amp;
    ctx.globalAlpha = a;
    ctx.beginPath();
    ctx.arc(x, y, f.r, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawSky(ctx, width, height);
  drawStars(ctx, S, p);
  drawMoon(ctx, S, p);

  drawHill(ctx, S, 0, width, height);
  drawTrees(ctx, S.far, '#2F3C86', null, '#2A3478');
  drawHill(ctx, S, 1, width, height);
  drawTrees(ctx, S.mid, '#2B3C8E', '#C9D6F4', '#232E78');
  drawHill(ctx, S, 2, width, height);
  drawTrees(ctx, S.near, '#12285A', '#F4F8FF', '#2A1E3F');

  drawLights(ctx, S, p);
  drawSnow(ctx, S, p);

  ctx.restore();
}

// KONSEP 8 — GOLDEN SPARKLE STARS & GEOMETRIC LINES
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function smooth(v) {
  v = v < 0 ? 0 : v > 1 ? 1 : v;
  return v * v * (3 - 2 * v);
}

// Easing sinusoidal periodik: kecepatan selalu positif dan kontinu, E(0)=0, E(1)=1
function ease(p) {
  return p + (0.35 * Math.sin(TAU * p)) / TAU;
}

function framePts(width, height, m, c) {
  return [
    [m + c, m], [width - m - c, m], [width - m, m + c], [width - m, height - m - c],
    [width - m - c, height - m], [m + c, height - m], [m, height - m - c], [m, m + c]
  ];
}

function polyLen(pts) {
  let L = 0;
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    L += Math.hypot(b[0] - a[0], b[1] - a[1]);
  }
  return L;
}

function buildScene(width, height) {
  const u = Math.min(width, height);
  const rnd = rng(20270108);

  // Bingkai ganda dengan sudut dipotong (chamfer); garis dalam sejajar dengan jarak d
  const d = 0.012 * u;
  const m1 = 0.04 * u;
  const c1 = 0.05 * u;
  const outer = framePts(width, height, m1, c1);
  const inner = framePts(width, height, m1 + d, c1 - (2 - Math.SQRT2) * d);
  const outerLen = polyLen(outer);
  const dashN = Math.round(outerLen / (0.15 * u));
  const dashPeriod = outerLen / dashN;

  // Dua bintang besar (kiri atas, kanan bawah) dengan cincin dekoratif
  const stars = [
    { x: 0.30 * u, y: 0.28 * u, dir: 1 },
    { x: width - 0.30 * u, y: height - 0.28 * u, dir: -1 }
  ];

  // Debu emas: jalur vertikal di kedua sisi area tengah
  const laneXs = [0.56 * u, 0.62 * u, 0.68 * u, 0.74 * u];
  const dust = [];
  for (let side = 0; side < 2; side++) {
    for (let li = 0; li < laneXs.length; li++) {
      const x = side === 0 ? laneXs[li] : width - laneXs[li];
      const near = li % 2 === 0;
      const off = rnd();
      const n = 6;
      for (let j = 0; j < n; j++) {
        dust.push({
          x: x,
          phase: (j + off) / n,
          cyc: near ? 2 : 1,
          r: u * (near ? 0.0045 : 0.0028),
          amp: u * 0.004,
          sk: 1 + ((j + li) % 2),
          sph: rnd() * TAU,
          col: (j + li) % 2 === 0 ? '#F2C14E' : '#FFE7A3'
        });
      }
    }
  }

  return {
    key: width + 'x' + height,
    u: u, d: d, outer: outer, inner: inner,
    dashPeriod: dashPeriod, stars: stars, dust: dust,
    dustTop: 0.16 * u, dustBot: height - 0.16 * u
  };
}

function pathPoly(ctx, pts) {
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
  ctx.closePath();
}

function drawSparkle(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.3;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
}

function drawBackground(ctx, width, height) {
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#02030F');
  g.addColorStop(1, '#0A1030');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawFrames(ctx, S, E) {
  const u = S.u;
  ctx.lineJoin = 'miter';
  ctx.lineCap = 'butt';

  // Bingkai dalam (solid, tipis)
  ctx.strokeStyle = 'rgba(212,165,55,0.55)';
  ctx.lineWidth = u * 0.0018;
  pathPoly(ctx, S.inner);
  ctx.stroke();

  // Bingkai luar: segmen emas bergerak pelan mengelilingi bingkai
  const P = S.dashPeriod;
  ctx.strokeStyle = '#F2C14E';
  ctx.lineWidth = u * 0.0026;
  ctx.setLineDash([P * 0.6, P * 0.4]);
  ctx.lineDashOffset = -2 * P * E;
  pathPoly(ctx, S.outer);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineJoin = 'round';
}

function drawBigStar(ctx, cx, cy, R, rot) {
  const ri = R * 0.28;
  const tip = [];
  const inn = [];
  for (let k = 0; k < 4; k++) {
    const a = rot + (k * Math.PI) / 2 - Math.PI / 2;
    tip.push([cx + Math.cos(a) * R, cy + Math.sin(a) * R]);
    inn.push([cx + Math.cos(a + Math.PI / 4) * ri, cy + Math.sin(a + Math.PI / 4) * ri]);
  }
  // Dasar gelap (seluruh bintang), lalu facet terang di atasnya
  ctx.fillStyle = '#B98A25';
  ctx.beginPath();
  for (let k = 0; k < 4; k++) {
    if (k === 0) ctx.moveTo(tip[k][0], tip[k][1]);
    else ctx.lineTo(tip[k][0], tip[k][1]);
    ctx.lineTo(inn[k][0], inn[k][1]);
  }
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#F7D774';
  ctx.beginPath();
  for (let k = 0; k < 4; k++) {
    ctx.moveTo(cx, cy);
    ctx.lineTo(tip[k][0], tip[k][1]);
    ctx.lineTo(inn[k][0], inn[k][1]);
    ctx.closePath();
  }
  ctx.fill();
}

function drawStarBlock(ctx, S, st, p, E) {
  const u = S.u;

  // Cincin tipis (solid) dan cincin putus-putus yang berputar
  ctx.strokeStyle = 'rgba(212,165,55,0.8)';
  ctx.lineWidth = u * 0.002;
  ctx.beginPath();
  ctx.arc(st.x, st.y, u * 0.175, 0, TAU);
  ctx.stroke();

  const r2 = u * 0.2;
  const period = (TAU * r2) / 72;
  ctx.strokeStyle = 'rgba(247,215,116,0.75)';
  ctx.lineWidth = u * 0.002;
  ctx.setLineDash([period * 0.5, period * 0.5]);
  ctx.lineDashOffset = st.dir * 3 * period * E;
  ctx.beginPath();
  ctx.arc(st.x, st.y, r2, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;

  // Bintang besar: berputar 90° per loop (simetri 4 sisi) dan berdenyut halus
  const scale = 1 + 0.04 * Math.sin(TAU * p);
  drawBigStar(ctx, st.x, st.y, u * 0.14 * scale, st.dir * (Math.PI / 2) * E);

  // Tiga sparkle mengorbit di antara dua cincin
  const rr = u * 0.1875;
  for (let i = 0; i < 3; i++) {
    const a = (i * TAU) / 3 + st.dir * (TAU / 3) * E;
    const f = 0.5 + 0.5 * Math.cos(a - TAU * 2 * p);
    ctx.fillStyle = '#FFE7A3';
    drawSparkle(ctx, st.x + Math.cos(a) * rr, st.y + Math.sin(a) * rr, u * (0.0055 + 0.003 * f));
  }
}

function drawFan(ctx, S, cx, cy, a0, a1, p) {
  const u = S.u;
  ctx.lineWidth = u * 0.0022;
  ctx.lineCap = 'butt';
  for (let i = 0; i < 6; i++) {
    const r = u * (0.06 + 0.04 * i);
    const al = 0.3 + 0.7 * (0.5 + 0.5 * Math.cos(TAU * (2 * p - i / 6)));
    ctx.strokeStyle = 'rgba(242,193,78,' + al.toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(cx, cy, r, a0, a1, false);
    ctx.stroke();
  }
  // Belah ketupat kecil di pusat kipas
  const s = u * 0.012;
  ctx.fillStyle = '#F2C14E';
  ctx.beginPath();
  ctx.moveTo(cx, cy - s);
  ctx.lineTo(cx + s, cy);
  ctx.lineTo(cx, cy + s);
  ctx.lineTo(cx - s, cy);
  ctx.closePath();
  ctx.fill();
}

function drawDividers(ctx, S, width, height, p) {
  const u = S.u;
  const ys = [0.11 * u, height - 0.11 * u];
  const tw = 0.5 + 0.5 * Math.sin(TAU * p);
  for (let i = 0; i < 2; i++) {
    const y = ys[i];
    ctx.strokeStyle = 'rgba(212,165,55,0.6)';
    ctx.lineWidth = u * 0.0018;
    ctx.lineCap = 'butt';
    ctx.beginPath();
    ctx.moveTo(width / 2 - 0.22 * u, y);
    ctx.lineTo(width / 2 - 0.03 * u, y);
    ctx.moveTo(width / 2 + 0.03 * u, y);
    ctx.lineTo(width / 2 + 0.22 * u, y);
    ctx.stroke();

    const s = u * (0.011 + 0.002 * tw);
    ctx.fillStyle = '#F7D774';
    ctx.beginPath();
    ctx.moveTo(width / 2, y - s);
    ctx.lineTo(width / 2 + s, y);
    ctx.lineTo(width / 2, y + s);
    ctx.lineTo(width / 2 - s, y);
    ctx.closePath();
    ctx.fill();
  }
}

function drawDust(ctx, S, p) {
  const u = S.u;
  const fade = u * 0.06;
  const span = S.dustBot - S.dustTop;
  for (let i = 0; i < S.dust.length; i++) {
    const f = S.dust[i];
    const prog = (((f.phase + f.cyc * p) % 1) + 1) % 1;
    const y = S.dustBot - prog * span;
    const a = smooth((y - S.dustTop) / fade) * smooth((S.dustBot - y) / fade) * 0.85;
    if (a < 0.01) continue;
    const x = f.x + Math.sin(TAU * f.sk * p + f.sph) * f.amp;
    ctx.globalAlpha = a;
    ctx.fillStyle = f.col;
    ctx.beginPath();
    ctx.arc(x, y, f.r, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;
  const E = ease(p);

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;
  const u = S.u;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawBackground(ctx, width, height);
  drawFrames(ctx, S, E);

  // Kipas Art Deco di kanan atas dan kiri bawah
  drawFan(ctx, S, width - 0.1 * u, 0.1 * u, Math.PI / 2, Math.PI, p);
  drawFan(ctx, S, 0.1 * u, height - 0.1 * u, -Math.PI / 2, 0, p);

  // Bintang besar dengan cincin di kiri atas dan kanan bawah
  drawStarBlock(ctx, S, S.stars[0], p, E);
  drawStarBlock(ctx, S, S.stars[1], p, E);

  drawDividers(ctx, S, width, height, p);
  drawDust(ctx, S, p);

  ctx.restore();
}

// KONSEP 9 — ROCKET LAUNCH TO NEW YEAR
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function smooth(v) {
  v = v < 0 ? 0 : v > 1 ? 1 : v;
  return v * v * (3 - 2 * v);
}

// Lingkaran penyusun awan (relatif terhadap skala s): [x, y, r]
const CLOUD_C = [[-0.45, -0.08, 0.32], [0, -0.22, 0.44], [0.48, -0.06, 0.30]];

function bez(P, t) {
  const m = 1 - t;
  const a = m * m * m;
  const b = 3 * m * m * t;
  const c = 3 * m * t * t;
  const d = t * t * t;
  return [
    a * P[0][0] + b * P[1][0] + c * P[2][0] + d * P[3][0],
    a * P[0][1] + b * P[1][1] + c * P[2][1] + d * P[3][1]
  ];
}

function buildScene(width, height) {
  const u = Math.min(width, height);
  const b = u * 0.01;
  const rnd = rng(20270109);

  const hillF = function (x) {
    return u * 0.92 + u * 0.018 * Math.sin((TAU * x) / (1.7 * u) + 0.4) + u * 0.01 * Math.sin((TAU * x) / (0.6 * u) + 1.3);
  };
  const hillB = function (x) {
    return u * 0.84 + u * 0.03 * Math.sin((TAU * x) / (2.1 * u) + 2.2) + u * 0.015 * Math.sin((TAU * x) / (0.8 * u) + 0.7);
  };

  // Landasan dan jalur roket (kurva bezier: naik tegak lalu melengkung ke kanan)
  const x0 = 0.46 * u;
  const yPad = hillF(x0) - 0.006 * u;
  const y0 = yPad - 9.2 * b;
  const P = [
    [x0, y0],
    [x0, y0 - 0.30 * u],
    [x0 + 0.12 * u, y0 - 0.58 * u],
    [x0 + 0.40 * u, y0 - 1.0 * u]
  ];
  const N = 600;
  const pts = [];
  const cum = [0];
  for (let i = 0; i <= N; i++) {
    pts.push(bez(P, i / N));
    if (i > 0) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  const L = cum[N];
  const posAt = function (d) {
    d = d < 0 ? 0 : d > L ? L : d;
    let lo = 0;
    let hi = N;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (cum[mid] <= d) lo = mid;
      else hi = mid;
    }
    const seg = cum[hi] - cum[lo] || 1;
    const f = (d - cum[lo]) / seg;
    const tx = pts[hi][0] - pts[lo][0];
    const ty = pts[hi][1] - pts[lo][1];
    const tl = Math.hypot(tx, ty) || 1;
    return {
      x: pts[lo][0] + (pts[hi][0] - pts[lo][0]) * f,
      y: pts[lo][1] + (pts[hi][1] - pts[lo][1]) * f,
      tx: tx / tl, ty: ty / tl
    };
  };
  const distToPath = function (x, y) {
    let best = Infinity;
    for (let i = 0; i < pts.length; i += 2) {
      const dd = Math.hypot(x - pts[i][0], y - pts[i][1]);
      if (dd < best) best = dd;
    }
    return best;
  };

  // Planet dan awan
  const planetA = { x: 0.22 * u, y: 0.26 * u, r: 0.11 * u, orbitR: 0.17 * u, moonR: 0.018 * u };
  const planetB = { x: width - 0.178 * u, y: 0.18 * u, r: 0.065 * u };
  const clouds = [
    { x: 0.16 * u, y: 0.60 * u, s: 0.08 * u, ph: 0.0 },
    { x: 0.13 * u, y: 0.72 * u, s: 0.08 * u, ph: 2.0 },
    { x: 1.30 * u, y: 0.70 * u, s: 0.10 * u, ph: 4.0 },
    { x: 1.60 * u, y: 0.66 * u, s: 0.085 * u, ph: 1.0 }
  ];
  const cloudAmp = u * 0.012;

  // Bintang statis (hindari jalur roket, planet, orbit bulan, dan bukit)
  const stars = [];
  let tries = 0;
  while (stars.length < 30 && tries < 8000) {
    tries++;
    const x = u * 0.03 + rnd() * (u * 0.97);
    const y = u * 0.03 + rnd() * (u * 0.70);
    if (distToPath(x, y) < 0.22 * u) continue;
    const da = Math.hypot(x - planetA.x, y - planetA.y);
    if (da < planetA.orbitR + planetA.moonR + 0.05 * u && da > planetA.r - 1) continue;
    let ok = true;
    for (let c = 0; c < clouds.length; c++) {
      if (Math.hypot(x - clouds[c].x, y - clouds[c].y) < clouds[c].s * 1.6) { ok = false; break; }
    }
    if (!ok) continue;
    for (let s = 0; s < stars.length; s++) {
      if (Math.hypot(x - stars[s].x, y - stars[s].y) < u * 0.07) { ok = false; break; }
    }
    if (!ok) continue;
    const sparkle = stars.length % 3 === 0;
    stars.push({
      x: x, y: y, sparkle: sparkle,
      r: sparkle ? u * (0.008 + rnd() * 0.004) : u * (0.002 + rnd() * 0.0015),
      ph: rnd() * TAU, k: 1 + Math.floor(rnd() * 2)
    });
  }

  // Tinggi permukaan terdekat (bukit / awan) untuk batas bintang jatuh
  const cloudTop = function (c, x) {
    let best = c.y - 0.02 * c.s;
    for (let i = 0; i < CLOUD_C.length; i++) {
      const cc = CLOUD_C[i];
      const rr = cc[2] * c.s + cloudAmp;
      const dx = x - (c.x + cc[0] * c.s);
      if (Math.abs(dx) < rr) best = Math.min(best, c.y + cc[1] * c.s - Math.sqrt(rr * rr - dx * dx));
    }
    return best;
  };
  const ground = function (x) {
    let g = Math.min(hillB(x), hillF(x));
    for (let i = 0; i < clouds.length; i++) {
      const c = clouds[i];
      if (Math.abs(x - c.x) < 1.1 * c.s + cloudAmp) g = Math.min(g, cloudTop(c, x));
    }
    return g;
  };

  // Bintang jatuh pelan di sisi kanan (jalur vertikal, jarak 0.05u)
  const falling = [];
  const span = height + u * 0.06;
  const nL = Math.floor((width - u * 0.04 - u * 1.04) / (u * 0.05)) + 1;
  for (let k = 0; k < nL; k++) {
    const x = u * 1.04 + k * u * 0.05;
    const r = u * (k % 2 === 0 ? 0.0035 : 0.002);
    const pad = r + u * 0.006;
    let gmin = Infinity;
    for (let dx = -0.01; dx <= 0.0100001; dx += 0.0025) gmin = Math.min(gmin, ground(x + dx * u));
    const inB = Math.abs(x - planetB.x) < planetB.r * 1.9 + u * 0.03;
    const off = rnd();
    for (let j = 0; j < 5; j++) {
      falling.push({
        x: x, r: r, lim: gmin - pad,
        yMin: inB ? planetB.y + planetB.r * 1.9 + u * 0.03 : -Infinity,
        phase: (j + off) / 5
      });
    }
  }

  return {
    key: width + 'x' + height,
    u: u, b: b, hillF: hillF, hillB: hillB,
    x0: x0, yPad: yPad, P0: P[0], path: { L: L, posAt: posAt }, distToPath: distToPath,
    planetA: planetA, planetB: planetB, clouds: clouds, cloudAmp: cloudAmp,
    stars: stars, falling: falling, span: span, ground: ground
  };
}

function drawSparkle(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.3;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
}

function drawSky(ctx, width, height) {
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#0A0B2E');
  g.addColorStop(0.6, '#1A1B5C');
  g.addColorStop(1, '#4A2C7A');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawStars(ctx, S, p) {
  for (let i = 0; i < S.stars.length; i++) {
    const s = S.stars[i];
    const tw = 0.5 + 0.5 * Math.sin(TAU * s.k * p + s.ph);
    ctx.globalAlpha = 0.4 + 0.6 * tw;
    if (s.sparkle) {
      ctx.fillStyle = '#FFF1CF';
      drawSparkle(ctx, s.x, s.y, s.r * (0.84 + 0.16 * tw));
    } else {
      ctx.fillStyle = '#D6D0FF';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, TAU);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
}

function drawFalling(ctx, S, p) {
  const u = S.u;
  const fade = u * 0.05;
  const yStart = -u * 0.03;
  ctx.fillStyle = '#FFF1CF';
  for (let i = 0; i < S.falling.length; i++) {
    const f = S.falling[i];
    const prog = (((f.phase + p) % 1) + 1) % 1;
    const y = yStart + prog * S.span;
    let a = smooth((f.lim - y) / fade);
    if (f.yMin > -1e8) a *= smooth((y - f.yMin) / fade);
    a *= 0.8;
    if (a < 0.01) continue;
    ctx.globalAlpha = a;
    ctx.beginPath();
    ctx.arc(f.x, y, f.r, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawPlanetA(ctx, S, p) {
  const A = S.planetA;
  const u = S.u;
  // Orbit tipis dan bulan kecil (1 putaran per loop)
  ctx.strokeStyle = 'rgba(255,241,207,0.14)';
  ctx.lineWidth = u * 0.002;
  ctx.beginPath();
  ctx.arc(A.x, A.y, A.orbitR, 0, TAU);
  ctx.stroke();

  ctx.save();
  ctx.beginPath();
  ctx.arc(A.x, A.y, A.r, 0, TAU);
  ctx.fillStyle = '#E07A5F';
  ctx.fill();
  ctx.clip();
  const bands = [[-0.55, 0.22, '#F2A07B'], [-0.05, 0.2, '#C9604A'], [0.42, 0.24, '#F2A07B']];
  for (let i = 0; i < bands.length; i++) {
    ctx.fillStyle = bands[i][2];
    ctx.fillRect(A.x - A.r, A.y + bands[i][0] * A.r, A.r * 2, bands[i][1] * A.r);
  }
  // Bayangan datar sisi kanan bawah
  ctx.fillStyle = 'rgba(40,20,70,0.22)';
  ctx.beginPath();
  ctx.rect(A.x - 2 * A.r, A.y - 2 * A.r, 4 * A.r, 4 * A.r);
  ctx.arc(A.x - 0.2 * A.r, A.y - 0.2 * A.r, A.r, 0, TAU);
  ctx.fill('evenodd');
  ctx.restore();

  const ma = TAU * p - Math.PI / 4;
  ctx.fillStyle = '#E9E3F7';
  ctx.beginPath();
  ctx.arc(A.x + Math.cos(ma) * A.orbitR, A.y + Math.sin(ma) * A.orbitR, A.moonR, 0, TAU);
  ctx.fill();
}

function drawPlanetB(ctx, S) {
  const B = S.planetB;
  const u = S.u;
  const rx = B.r * 1.8;
  const ry = B.r * 0.4;
  const tilt = -0.31;
  ctx.lineWidth = u * 0.008;
  ctx.strokeStyle = '#E8C9A0';
  // Bagian cincin di belakang planet
  ctx.beginPath();
  ctx.ellipse(B.x, B.y, rx, ry, tilt, Math.PI, TAU);
  ctx.stroke();
  ctx.fillStyle = '#7C6CE0';
  ctx.beginPath();
  ctx.arc(B.x, B.y, B.r, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#6355CC';
  ctx.beginPath();
  ctx.arc(B.x, B.y, B.r, -0.2, Math.PI * 0.8);
  ctx.closePath();
  ctx.fill();
  // Bagian cincin di depan planet
  ctx.beginPath();
  ctx.ellipse(B.x, B.y, rx, ry, tilt, 0, Math.PI);
  ctx.stroke();
}

function drawClouds(ctx, S, p) {
  for (let i = 0; i < S.clouds.length; i++) {
    const c = S.clouds[i];
    const x = c.x + Math.sin(TAU * p + c.ph) * S.cloudAmp;
    const s = c.s;
    ctx.fillStyle = '#4A5AB0';
    ctx.fillRect(x - 0.9 * s, c.y - 0.02 * s, 1.8 * s, 0.2 * s);
    for (let k = 0; k < CLOUD_C.length; k++) {
      const cc = CLOUD_C[k];
      ctx.beginPath();
      ctx.arc(x + cc[0] * s, c.y + cc[1] * s, cc[2] * s, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = '#3E4DA2';
    ctx.fillRect(x - 0.9 * s, c.y + 0.12 * s, 1.8 * s, 0.06 * s);
  }
}

function drawHills(ctx, S, width, height) {
  const u = S.u;
  const step = u * 0.01;
  const x0 = -u * 0.02;
  const x1 = width + u * 0.02;
  const layers = [[S.hillB, '#1E2A70'], [S.hillF, '#111A4F']];
  for (let l = 0; l < layers.length; l++) {
    ctx.fillStyle = layers[l][1];
    ctx.beginPath();
    for (let x = x0; x <= x1 + 0.5; x += step) {
      const y = layers[l][0](x);
      if (x === x0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.lineTo(x1, height + u * 0.02);
    ctx.lineTo(x0, height + u * 0.02);
    ctx.closePath();
    ctx.fill();
  }
}

function drawPad(ctx, S) {
  const u = S.u;
  const x = S.x0;
  // Platform
  ctx.fillStyle = '#5B6AA8';
  ctx.fillRect(x - 0.05 * u, S.yPad, 0.1 * u, 0.02 * u);
  ctx.fillStyle = '#46548F';
  ctx.fillRect(x - 0.05 * u, S.yPad + 0.012 * u, 0.1 * u, 0.008 * u);
  // Menara di sisi kiri
  const tx = x - 0.075 * u;
  ctx.fillStyle = '#5B6AA8';
  ctx.fillRect(tx - 0.006 * u, S.yPad - 0.17 * u, 0.012 * u, 0.17 * u);
  ctx.fillStyle = '#FF6B6B';
  ctx.fillRect(tx - 0.009 * u, S.yPad - 0.17 * u, 0.018 * u, 0.008 * u);
}

function drawRocket(ctx, b, flameLen) {
  ctx.translate(0, 1.8 * b);

  // Api (dua lapis, datar)
  if (flameLen > 0) {
    ctx.fillStyle = '#FF8A3D';
    ctx.beginPath();
    ctx.moveTo(-1.7 * b, 7.4 * b);
    ctx.quadraticCurveTo(-2.2 * b, 7.4 * b + flameLen * 0.5, 0, 7.4 * b + flameLen);
    ctx.quadraticCurveTo(2.2 * b, 7.4 * b + flameLen * 0.5, 1.7 * b, 7.4 * b);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#FFD23F';
    ctx.beginPath();
    ctx.moveTo(-1.0 * b, 7.4 * b);
    ctx.quadraticCurveTo(-1.3 * b, 7.4 * b + flameLen * 0.3, 0, 7.4 * b + flameLen * 0.62);
    ctx.quadraticCurveTo(1.3 * b, 7.4 * b + flameLen * 0.3, 1.0 * b, 7.4 * b);
    ctx.closePath();
    ctx.fill();
  }

  // Sirip
  ctx.fillStyle = '#FF6B6B';
  ctx.beginPath();
  ctx.moveTo(-2.6 * b, 1.5 * b);
  ctx.lineTo(-5.2 * b, 7.4 * b);
  ctx.lineTo(-2.6 * b, 5.6 * b);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#E04F5F';
  ctx.beginPath();
  ctx.moveTo(2.6 * b, 1.5 * b);
  ctx.lineTo(5.2 * b, 7.4 * b);
  ctx.lineTo(2.6 * b, 5.6 * b);
  ctx.closePath();
  ctx.fill();

  // Nozzle
  ctx.fillStyle = '#8C97C4';
  ctx.beginPath();
  ctx.moveTo(-1.5 * b, 6 * b);
  ctx.lineTo(1.5 * b, 6 * b);
  ctx.lineTo(1.9 * b, 7.4 * b);
  ctx.lineTo(-1.9 * b, 7.4 * b);
  ctx.closePath();
  ctx.fill();

  // Badan
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(-2.6 * b, 6 * b);
  ctx.lineTo(-2.6 * b, -3 * b);
  ctx.quadraticCurveTo(-2.6 * b, -8 * b, 0, -11 * b);
  ctx.quadraticCurveTo(2.6 * b, -8 * b, 2.6 * b, -3 * b);
  ctx.lineTo(2.6 * b, 6 * b);
  ctx.closePath();
  ctx.fillStyle = '#F4F6FF';
  ctx.fill();
  ctx.clip();
  ctx.fillStyle = '#D5DAF2';
  ctx.fillRect(1.3 * b, -4.2 * b, 1.7 * b, 11.2 * b);
  ctx.fillStyle = '#FF6B6B';
  ctx.fillRect(-3 * b, -12 * b, 6 * b, 7.8 * b);
  ctx.fillStyle = '#E04F5F';
  ctx.fillRect(1.3 * b, -12 * b, 1.7 * b, 7.8 * b);
  ctx.fillStyle = '#F2C14E';
  ctx.fillRect(-3 * b, 2.8 * b, 6 * b, 1.2 * b);
  ctx.restore();

  // Jendela
  ctx.fillStyle = '#1B2A6B';
  ctx.beginPath();
  ctx.arc(0, -0.8 * b, 1.6 * b, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#7FE3F0';
  ctx.beginPath();
  ctx.arc(0, -0.8 * b, 1.15 * b, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#FFF1CF';
  ctx.beginPath();
  ctx.arc(-0.4 * b, -1.2 * b, 0.35 * b, 0, TAU);
  ctx.fill();
}

function drawLaunch(ctx, S, p) {
  const u = S.u;
  const b = S.b;
  const L = S.path.L;
  const q = p;
  const q0 = 0.12;
  const q1 = 0.9;
  const T = 9.2 * b + 0.075 * u + 0.023 * u; // jarak dari pusat roket ke titik lahir asap
  const ds = 0.07 * u;

  const ageOf = function (qk) {
    return (((q - qk) % 1) + 1) % 1;
  };
  const birth = function (d) {
    const dd = d + T;
    if (dd > L) return -1;
    return q0 + Math.sqrt(dd / L) * (q1 - q0);
  };

  // Asap: lingkaran membesar dan memudar, jarak antar-asap lebih besar dari diameter maksimum
  const life = 0.14;
  ctx.fillStyle = '#C7CBF2';
  for (let k = 0; ; k++) {
    const d = (k + 0.5) * ds;
    if (d + T > L) break;
    if (d < 0.12 * u) continue;
    const qk = birth(d);
    if (qk < 0) continue;
    const a = ageOf(qk);
    if (a >= life) continue;
    const f = a / life;
    const al = smooth(a / 0.012) * (1 - smooth(f)) * 0.8;
    if (al < 0.01) continue;
    const pos = S.path.posAt(d);
    ctx.globalAlpha = al;
    ctx.beginPath();
    ctx.arc(pos.x, pos.y, u * (0.01 + 0.018 * smooth(f)), 0, TAU);
    ctx.fill();
  }

  // Percikan: titik emas di kedua sisi jejak, bergeser keluar saat memudar
  const lifeS = 0.08;
  ctx.fillStyle = '#FFD23F';
  for (let j = 2; ; j++) {
    const d = j * ds;
    if (d + T > L) break;
    const qk = birth(d);
    if (qk < 0) continue;
    const a = ageOf(qk);
    if (a >= lifeS) continue;
    const f = a / lifeS;
    const al = smooth(a / 0.01) * (1 - smooth(f));
    if (al < 0.01) continue;
    const pos = S.path.posAt(d);
    const lat = u * (0.03 + 0.025 * smooth(f));
    const r = u * 0.0042 * (1 - 0.5 * smooth(f));
    ctx.globalAlpha = al;
    for (let s = -1; s <= 1; s += 2) {
      ctx.beginPath();
      ctx.arc(pos.x - pos.ty * lat * s, pos.y + pos.tx * lat * s, r, 0, TAU);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;

  // Roket
  let d = 0;
  if (q >= q0) {
    const x = Math.min(1, (q - q0) / (q1 - q0));
    d = L * x * x;
  }
  if (q >= q1) return;
  const ra = smooth(q / 0.04);
  if (ra <= 0.001) return;
  const ign = smooth((q - 0.04) / 0.08);
  const flame = u * 0.075 * ign * (0.92 + 0.08 * Math.sin(TAU * 8 * p));
  const pos = S.path.posAt(d);
  ctx.save();
  ctx.globalAlpha = ra;
  ctx.translate(pos.x, pos.y);
  ctx.rotate(Math.atan2(pos.tx, -pos.ty));
  drawRocket(ctx, b, flame);
  ctx.restore();
  ctx.globalAlpha = 1;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawSky(ctx, width, height);
  drawStars(ctx, S, p);
  drawFalling(ctx, S, p);
  drawPlanetA(ctx, S, p);
  drawPlanetB(ctx, S);
  drawClouds(ctx, S, p);
  drawHills(ctx, S, width, height);
  drawPad(ctx, S);
  drawLaunch(ctx, S, p);

  ctx.restore();
}

// KONSEP 10 — DISCO BALL & NEON PARTY NIGHT
// New Year | 20 detik | 1 scene | 16:9 | 4K | Modern Flat Vector + Open Copy Space
// Tanpa glow / bloom / shadowBlur. Seluruh gerakan memakai siklus bilangan bulat per 20 detik (loop seamless).
// Catatan export: bitrate 100 Mbps diatur di pengaturan render/export (bukan dari fungsi draw).

const TAU = Math.PI * 2;
let SCENE = null;

const NEON = ['#FF2E93', '#2EE6FF', '#FFE14D', '#9B5CFF', '#7CFF6B'];

function hexRgb(h) {
  return [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
}
const NEON_RGB = NEON.map(hexRgb);

function mixRgb(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function rgbStr(c) {
  return 'rgb(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ')';
}

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function smooth(v) {
  v = v < 0 ? 0 : v > 1 ? 1 : v;
  return v * v * (3 - 2 * v);
}

// Easing sinusoidal periodik: kecepatan selalu positif dan kontinu, E(0)=0, E(1)=1
function ease(p) {
  return p + (0.35 * Math.sin(TAU * p)) / TAU;
}

function buildScene(width, height) {
  const u = Math.min(width, height);
  const rnd = rng(20270110);
  const floorTop = u * 0.8;

  const ball = { x: width / 2, y: 0.27 * u, R: 0.16 * u };

  // Sorotan: dua di kiri (sapuan sejajar), satu di tepi kanan (sapuan berlawanan arah)
  const alpha = (2.8 * Math.PI) / 180;
  const amp = (7 * Math.PI) / 180;
  const fy = 0.05 * u;
  const fixtures = [
    { x: 0.40 * u, sgn: 1, col: NEON[0], ci: 0 },
    { x: 0.62 * u, sgn: 1, col: NEON[1], ci: 1 },
    { x: width - 0.158 * u, sgn: -1, col: NEON[2], ci: 2 }
  ];

  // Sinar pantulan bola disko: jalur radial (sudut berjarak 10°), menjauhi tali, balon, dan lantai
  const angles = [];
  for (let a = 180; a <= 250; a += 10) angles.push(a);
  for (let a = -70; a <= 0; a += 10) angles.push(a);
  const sMin = ball.R + 0.03 * u;
  const sMax = 2.0 * u;
  const rays = [];
  angles.forEach(function (deg, ri) {
    const off = rnd();
    const n = 6;
    for (let j = 0; j < n; j++) {
      rays.push({
        dx: Math.cos((deg * Math.PI) / 180),
        dy: Math.sin((deg * Math.PI) / 180),
        phase: (j + off) / n,
        col: NEON[ri % 5],
        diamond: ri % 2 === 1
      });
    }
  });

  // Balon siluet di kiri bawah, masing-masing terikat ke pemberat di tepi lantai
  const balloons = [
    { ax: 0.05 * u, L: 0.30 * u, rx: 0.030 * u, rim: NEON[0], k: 1, ph: 0.4 },
    { ax: 0.12 * u, L: 0.38 * u, rx: 0.032 * u, rim: NEON[1], k: 2, ph: 2.1 },
    { ax: 0.19 * u, L: 0.25 * u, rx: 0.030 * u, rim: NEON[3], k: 1, ph: 4.0 }
  ];

  // Lantai perspektif
  const R = 5;
  const NC = 32;
  const yb = [];
  const cw = [];
  const cw0 = width / NC;
  const cw1 = 0.12 * u;
  for (let k = 0; k <= R; k++) {
    const y = floorTop + (height - floorTop) * Math.pow(k / R, 1.5);
    yb.push(y);
    cw.push(cw0 + (cw1 - cw0) * ((y - floorTop) / (height - floorTop)));
  }
  const xAt = function (k, c) {
    return width / 2 + (c - NC / 2) * cw[k];
  };
  const tiles = [];
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < NC; c++) {
      const q = [
        [xAt(r, c), yb[r]], [xAt(r, c + 1), yb[r]],
        [xAt(r + 1, c + 1), yb[r + 1]], [xAt(r + 1, c), yb[r + 1]]
      ];
      const minX = Math.min(q[0][0], q[3][0]);
      const maxX = Math.max(q[1][0], q[2][0]);
      if (maxX < 0 || minX > width) continue;
      let cxm = 0;
      let cym = 0;
      for (let i = 0; i < 4; i++) { cxm += q[i][0] / 4; cym += q[i][1] / 4; }
      tiles.push({ r: r, c: c, q: q, cx: cxm, cy: cym, topX: (q[0][0] + q[1][0]) / 2 });
    }
  }

  return {
    key: width + 'x' + height,
    u: u, floorTop: floorTop, ball: ball,
    alpha: alpha, amp: amp, fy: fy, fixtures: fixtures,
    rays: rays, sMin: sMin, sMax: sMax,
    balloons: balloons, tiles: tiles, cw0: cw0, R: R
  };
}

// Sudut sapuan sorotan (rad dari sumbu vertikal ke bawah)
function beamSweep(S, f, p) {
  return f.sgn * S.amp * Math.sin(TAU * 2 * p);
}

// Keadaan satu titik pantulan; alfa 0 saat menyentuh sinar sorotan, tepi layar, atau bola
function spotState(S, width, ray, p) {
  const u = S.u;
  const prog = (((ray.phase + p) % 1) + 1) % 1;
  const s = S.sMin + prog * (S.sMax - S.sMin);
  const x = S.ball.x + ray.dx * s;
  const y = S.ball.y + ray.dy * s;
  const r = Math.min(u * 0.014, u * (0.006 + 0.005 * (s / u)));

  let a = smooth((s - S.sMin) / (0.04 * u));
  a *= smooth(Math.min(x, width - x) / (0.05 * u));
  a *= smooth((y - 0.08 * u) / (0.05 * u));

  for (let i = 0; i < S.fixtures.length; i++) {
    const f = S.fixtures[i];
    const th = Math.PI / 2 + beamSweep(S, f, p);
    const vx = x - f.x;
    const vy = y - S.fy;
    const dist = Math.hypot(vx, vy);
    let dA = Math.atan2(vy, vx) - th;
    while (dA > Math.PI) dA -= TAU;
    while (dA < -Math.PI) dA += TAU;
    const out = Math.abs(dA) - S.alpha;
    const dEdge = out >= Math.PI / 2 ? dist : dist * Math.sin(Math.max(0, out));
    a *= smooth((dEdge - r - 0.002 * u) / (0.03 * u));
  }
  return { x: x, y: y, r: r, a: a * 0.95 };
}

function drawWall(ctx, S, width, height) {
  const u = S.u;
  const g = ctx.createLinearGradient(0, 0, 0, S.floorTop);
  g.addColorStop(0, '#0B0620');
  g.addColorStop(1, '#1B0F45');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, S.floorTop);

  // Panel dinding tipis
  ctx.strokeStyle = 'rgba(255,255,255,0.05)';
  ctx.lineWidth = u * 0.002;
  ctx.beginPath();
  for (let x = u * 0.2; x < width; x += u * 0.2) {
    ctx.moveTo(x, 0);
    ctx.lineTo(x, S.floorTop);
  }
  ctx.stroke();
}

function beamGeom(S, f, p) {
  const th = Math.PI / 2 + beamSweep(S, f, p);
  const tA = th - S.alpha;
  const tB = th + S.alpha;
  const pt = function (ang) {
    const t = (S.floorTop - S.fy) / Math.sin(ang);
    return [f.x + t * Math.cos(ang), S.floorTop];
  };
  const a = pt(tA);
  const b = pt(tB);
  return { th: th, a: a, b: b, cx: (a[0] + b[0]) / 2, hw: Math.abs(b[0] - a[0]) / 2 };
}

function drawFloor(ctx, S, p, width, height) {
  const u = S.u;
  const base0 = [20, 24, 63];
  const base1 = [28, 33, 96];
  const beams = S.fixtures.map(function (f) { return beamGeom(S, f, p); });
  const rowTint = [0.6, 0.5, 0.4, 0.3, 0.22];

  // Dasar lantai
  ctx.fillStyle = '#0A0B2A';
  ctx.fillRect(0, S.floorTop, width, height - S.floorTop);

  for (let i = 0; i < S.tiles.length; i++) {
    const t = S.tiles[i];
    const lvl = 0.5 + 0.5 * Math.cos(TAU * (2 * p - (t.c * 0.11 + t.r * 0.23)));
    let col = mixRgb((t.r + t.c) % 2 === 0 ? base0 : base1, NEON_RGB[t.c % 5], 0.38 * lvl * lvl);
    for (let b = 0; b < beams.length; b++) {
      const cov = smooth(1 - Math.abs(t.topX - beams[b].cx) / (beams[b].hw + S.cw0 * 0.6));
      if (cov > 0) col = mixRgb(col, NEON_RGB[S.fixtures[b].ci], cov * rowTint[t.r]);
    }
    ctx.fillStyle = rgbStr(col);
    ctx.beginPath();
    for (let k = 0; k < 4; k++) {
      const x = t.cx + (t.q[k][0] - t.cx) * 0.96;
      const y = t.cy + (t.q[k][1] - t.cy) * 0.96;
      if (k === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
  }
}

function drawBeams(ctx, S, p) {
  for (let i = 0; i < S.fixtures.length; i++) {
    const f = S.fixtures[i];
    const g = beamGeom(S, f, p);
    ctx.fillStyle = f.col;
    ctx.globalAlpha = 0.16;
    ctx.beginPath();
    ctx.moveTo(f.x, S.fy);
    ctx.lineTo(g.a[0], g.a[1]);
    ctx.lineTo(g.b[0], g.b[1]);
    ctx.closePath();
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawFixtures(ctx, S, p) {
  const u = S.u;
  for (let i = 0; i < S.fixtures.length; i++) {
    const f = S.fixtures[i];
    ctx.save();
    ctx.translate(f.x, S.fy);
    ctx.rotate(beamSweep(S, f, p));
    // Dudukan
    ctx.fillStyle = '#2A2F6B';
    ctx.fillRect(-0.02 * u, -0.05 * u, 0.04 * u, 0.04 * u);
    // Lensa
    ctx.fillStyle = '#1A1E52';
    ctx.beginPath();
    ctx.moveTo(-0.018 * u, -0.01 * u);
    ctx.lineTo(0.018 * u, -0.01 * u);
    ctx.lineTo(0.012 * u, 0);
    ctx.lineTo(-0.012 * u, 0);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    ctx.fillStyle = f.col;
    ctx.beginPath();
    ctx.arc(f.x, S.fy, 0.006 * u, 0, TAU);
    ctx.fill();
  }
}

function drawSpots(ctx, S, width, p) {
  for (let i = 0; i < S.rays.length; i++) {
    const ray = S.rays[i];
    const st = spotState(S, width, ray, p);
    if (st.a < 0.01) continue;
    ctx.globalAlpha = st.a;
    ctx.fillStyle = ray.col;
    ctx.beginPath();
    if (ray.diamond) {
      ctx.moveTo(st.x, st.y - st.r * 1.2);
      ctx.lineTo(st.x + st.r * 1.2, st.y);
      ctx.lineTo(st.x, st.y + st.r * 1.2);
      ctx.lineTo(st.x - st.r * 1.2, st.y);
      ctx.closePath();
    } else {
      ctx.arc(st.x, st.y, st.r, 0, TAU);
    }
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function tilePoint(cx, cy, R, lat, phi) {
  return [cx + R * Math.cos(lat) * Math.sin(phi), cy - R * Math.sin(lat)];
}

function drawBall(ctx, S, p, E) {
  const u = S.u;
  const cx = S.ball.x;
  const cy = S.ball.y;
  const R = S.ball.R;
  const NL = 24;
  const NB = 12;
  const stepL = TAU / NL;
  const stepB = Math.PI / NB;
  const psi = 4 * stepL * E; // 4 ubin per loop (pola ubin berperiode 4)

  // Tali gantung
  ctx.strokeStyle = '#8089C8';
  ctx.lineWidth = u * 0.004;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(cx, 0);
  ctx.lineTo(cx, cy - R - 0.012 * u);
  ctx.stroke();
  ctx.fillStyle = '#8089C8';
  ctx.beginPath();
  ctx.arc(cx, cy - R - 0.012 * u, 0.007 * u, 0, TAU);
  ctx.fill();

  // Dasar bola (celah antar ubin)
  ctx.fillStyle = '#23275A';
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, TAU);
  ctx.fill();

  const dl = 0.014;
  const dp = 0.014;
  const dark = [62, 68, 134];
  const light = [232, 238, 255];
  for (let i = 0; i < NB; i++) {
    const lat0 = -Math.PI / 2 + i * stepB + dl;
    const lat1 = -Math.PI / 2 + (i + 1) * stepB - dl;
    const latM = (lat0 + lat1) / 2;
    for (let j = 0; j < NL; j++) {
      let f0 = j * stepL + psi;
      f0 = (((f0 + Math.PI) % TAU) + TAU) % TAU - Math.PI;
      const f1 = f0 + stepL;
      const a = Math.max(f0, -Math.PI / 2);
      const b = Math.min(f1, Math.PI / 2);
      if (b - a < 2 * dp + 0.004) continue;
      const aa = a + dp;
      const bb = b - dp;
      const jm = j % 4;
      const facing = Math.max(0, Math.cos(latM) * Math.cos((aa + bb) / 2));
      const shim = smooth(0.5 + 0.5 * Math.cos(TAU * 2 * p - (i * 0.8 + jm * 1.4)));
      let col = mixRgb(dark, light, Math.pow(facing, 0.7));
      col = mixRgb(col, NEON_RGB[(i + jm) % 5], 0.22 * shim);
      col = mixRgb(col, [255, 255, 255], 0.5 * shim * shim);
      ctx.fillStyle = rgbStr(col);
      ctx.beginPath();
      let pt = tilePoint(cx, cy, R, lat0, aa);
      ctx.moveTo(pt[0], pt[1]);
      pt = tilePoint(cx, cy, R, lat0, bb);
      ctx.lineTo(pt[0], pt[1]);
      for (let s = 1; s <= 3; s++) {
        pt = tilePoint(cx, cy, R, lat0 + ((lat1 - lat0) * s) / 3, bb);
        ctx.lineTo(pt[0], pt[1]);
      }
      pt = tilePoint(cx, cy, R, lat1, aa);
      ctx.lineTo(pt[0], pt[1]);
      for (let s = 2; s >= 0; s--) {
        pt = tilePoint(cx, cy, R, lat0 + ((lat1 - lat0) * s) / 3, aa);
        ctx.lineTo(pt[0], pt[1]);
      }
      ctx.closePath();
      ctx.fill();
    }
  }

  // Garis tepi bola
  ctx.strokeStyle = 'rgba(128,137,200,0.6)';
  ctx.lineWidth = u * 0.003;
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, TAU);
  ctx.stroke();
}

function drawBalloons(ctx, S, p) {
  const u = S.u;
  for (let i = 0; i < S.balloons.length; i++) {
    const b = S.balloons[i];
    const ang = 0.045 * Math.sin(TAU * b.k * p + b.ph);
    const ry = b.rx * 1.2;
    ctx.save();
    ctx.translate(b.ax, S.floorTop);
    ctx.rotate(ang);

    // Tali
    ctx.strokeStyle = '#2A2F6B';
    ctx.lineWidth = u * 0.0025;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(u * 0.01, -b.L * 0.5, 0, -(b.L - ry - u * 0.012));
    ctx.stroke();

    // Pemberat
    ctx.fillStyle = '#2A2F6B';
    ctx.beginPath();
    ctx.arc(0, -u * 0.004, u * 0.006, 0, TAU);
    ctx.fill();

    // Siluet balon + simpul
    ctx.fillStyle = '#0A0D30';
    ctx.beginPath();
    ctx.ellipse(0, -b.L, b.rx, ry, 0, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(0, -b.L + ry - u * 0.002);
    ctx.lineTo(-u * 0.007, -b.L + ry + u * 0.01);
    ctx.lineTo(u * 0.007, -b.L + ry + u * 0.01);
    ctx.closePath();
    ctx.fill();

    // Aksen tepi neon (garis tipis, bukan cahaya)
    ctx.strokeStyle = b.rim;
    ctx.lineWidth = u * 0.0028;
    ctx.beginPath();
    ctx.ellipse(0, -b.L, b.rx * 0.82, ry * 0.82, 0, Math.PI * 1.05, Math.PI * 1.55);
    ctx.stroke();
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Fase loop 0..1 (seluruh siklus gerak = bilangan bulat per 20 detik)
  const p = (currentScene + sceneProgress) / sceneCount;
  const E = ease(p);

  const minSide = Math.min(width, height);
  if (!SCENE || SCENE.key !== width + 'x' + height) SCENE = buildScene(width, height);
  const S = SCENE;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.lineJoin = 'round';

  drawWall(ctx, S, width, height);
  drawFloor(ctx, S, p, width, height);
  drawBeams(ctx, S, p);
  drawSpots(ctx, S, width, p);
  drawFixtures(ctx, S, p);
  drawBall(ctx, S, p, E);
  drawBalloons(ctx, S, p);

  ctx.restore();
}
